private enum NoteTextNormalizer {
    private static let spokenPunctuation: [(String, String)] = [
        ("新的一行", "\n"),
        ("另起一行", "\n"),
        ("换行", "\n"),
        ("句号", "。"),
        ("逗号", "，"),
        ("顿号", "、"),
        ("问号", "？"),
        ("感叹号", "！"),
        ("叹号", "！"),
        ("冒号", "："),
        ("分号", "；"),
        ("省略号", "……"),
    ]

    private static let closingPunctuation = CharacterSet(charactersIn: "。！？!?…；;：:，,、）)]】》」』”’\"'")

    static func normalized(_ rawText: String) -> String {
        var text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return text }

        for (spoken, mark) in spokenPunctuation {
            text = text.replacingOccurrences(of: spoken, with: mark)
        }
        text = text.replacingOccurrences(of: "\\s+([，。！？；：、,.!?;:])", with: "$1", options: .regularExpression)
        text = text.replacingOccurrences(of: "([，。！？；：、,.!?;:])\\s+", with: "$1", options: .regularExpression)
        text = text.replacingOccurrences(of: "([。！？!?]){2,}", with: "$1", options: .regularExpression)
        text = text.replacingOccurrences(of: "\\n{3,}", with: "\n\n", options: .regularExpression)
        return ensureSentenceEnding(text.trimmingCharacters(in: .whitespacesAndNewlines))
    }

    private static func ensureSentenceEnding(_ text: String) -> String {
        guard let lastScalar = text.unicodeScalars.last,
              !closingPunctuation.contains(lastScalar)
        else {
            return text
        }
        return isEnglishOnly(text) ? text + "." : text + "。"
    }

    private static func isEnglishOnly(_ text: String) -> Bool {
        let hasLetter = text.unicodeScalars.contains { scalar in
            (65...90).contains(Int(scalar.value)) || (97...122).contains(Int(scalar.value))
        }
        let hasCJK = text.unicodeScalars.contains { scalar in
            (0x4E00...0x9FFF).contains(Int(scalar.value))
        }
        return hasLetter && !hasCJK
    }
}

final class NoteSpeechController: NSObject, AVAudioRecorderDelegate {
    private weak var textView: NSTextView?
    private weak var statusLabel: NSTextField?
    private weak var recordButton: NSButton?
    private weak var providerPopup: NSPopUpButton?
    private let bookID: String?
    private let readerAPI: ReaderAPIClient
    private var recorder: AVAudioRecorder?
    private var audioURL: URL?
    private var audioDurationSeconds: Double?
    private var appleSpeechTask: SFSpeechRecognitionTask?
    private var isTranscribing = false
    private var silenceTimer: Timer?
    private var recordingStartedAt: Date?
    private var lastSpeechAt: Date?
    private var heardSpeech = false
    private(set) var latestAudioNoteID: String?
    var onTranscriptionFinished: ((String?) -> Void)?
    var isTranscriptionInProgress: Bool { isTranscribing }
    var isUserAudioWorkActive: Bool {
        recorder?.isRecording == true || isTranscribing
    }

    private struct FunASRPaths {
        let python: URL
        let worker: URL
        let source: String
    }

    private let funASRPythonDefaultsKey = "SentenceReader.funASRPythonPath.v1"
    private let funASRWorkerDefaultsKey = "SentenceReader.funASRWorkerPath.v1"
    private let funASRPythonEnvKey = "SENTENCE_READER_FUNASR_PYTHON"
    private let funASRWorkerEnvKey = "SENTENCE_READER_FUNASR_WORKER"
    private let funASRPythonDefaultPath = (NSHomeDirectory() as NSString).appendingPathComponent("Library/Application Support/SentenceReader/FunASR/.venv/bin/python")
    private let funASRWorkerDefaultPath = (NSHomeDirectory() as NSString).appendingPathComponent("Library/Application Support/SentenceReader/FunASR/funasr_worker.py")
    private let funASRServerPort = 18081

    init(textView: NSTextView, statusLabel: NSTextField, recordButton: NSButton, providerPopup: NSPopUpButton, bookID: String?, readerAPI: ReaderAPIClient) {
        self.textView = textView
        self.statusLabel = statusLabel
        self.recordButton = recordButton
        self.providerPopup = providerPopup
        self.bookID = bookID
        self.readerAPI = readerAPI
        super.init()
    }

    @objc func toggleRecording(_ sender: NSButton) {
        if recorder?.isRecording == true {
            stopRecordingAndTranscribe()
        } else if !isTranscribing {
            requestMicrophoneAndStart()
        }
    }

    func beginVoiceFirstRecording() {
        guard recorder?.isRecording != true, !isTranscribing else {
            return
        }
        requestMicrophoneAndStart()
    }

    func cancel() {
        silenceTimer?.invalidate()
        silenceTimer = nil
        recorder?.stop()
        recorder = nil
        appleSpeechTask?.cancel()
        appleSpeechTask = nil
        if isTranscribing, let audioNoteID = latestAudioNoteID {
            DispatchQueue.global(qos: .utility).async { [readerAPI] in
                _ = readerAPI.updateAudioNote(
                    audioNoteID: audioNoteID,
                    annotationID: nil,
                    provider: nil,
                    transcript: nil,
                    status: "failed",
                    errorMessage: "用户取消了备注编辑"
                )
            }
        }
        isTranscribing = false
    }

    func prepareForSave() -> String? {
        if recorder?.isRecording == true {
            stopRecordingAndTranscribe()
        }
        return latestAudioNoteID
    }

    @objc func providerChanged(_ sender: NSPopUpButton) {
        SpeechTranscriptionProvider.save(SpeechTranscriptionProvider.fromTitle(sender.titleOfSelectedItem))
        updateStatus("")
    }

    private func selectedProvider() -> SpeechTranscriptionProvider {
        SpeechTranscriptionProvider.fromTitle(providerPopup?.titleOfSelectedItem)
    }

    private func requestMicrophoneAndStart() {
        let status = AVCaptureDevice.authorizationStatus(for: .audio)
        if status == .authorized {
            startRecording()
            return
        }
        if status == .denied || status == .restricted {
            updateStatus("麦克风权限未开启，请到系统设置允许 Click 使用麦克风。")
            return
        }

        updateStatus("正在请求麦克风权限...")
        AVCaptureDevice.requestAccess(for: .audio) { [weak self] granted in
            DispatchQueue.main.async {
                guard let self else { return }
                granted ? self.startRecording() : self.updateStatus("麦克风权限未允许，无法录音。")
            }
        }
    }

    private func startRecording() {
        do {
            let directory = try audioNotesDirectory()
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            let url = directory.appendingPathComponent("note-\(UUID().uuidString).wav")
            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatLinearPCM),
                AVSampleRateKey: 16_000,
                AVNumberOfChannelsKey: 1,
                AVLinearPCMBitDepthKey: 16,
                AVLinearPCMIsFloatKey: false,
                AVLinearPCMIsBigEndianKey: false,
            ]

            let recorder = try AVAudioRecorder(url: url, settings: settings)
            recorder.delegate = self
            recorder.prepareToRecord()
            recorder.isMeteringEnabled = true
            guard recorder.record() else {
                updateStatus("录音启动失败，请检查麦克风输入设备。")
                return
            }

            self.audioURL = url
            self.audioDurationSeconds = nil
            self.recorder = recorder
            self.recordingStartedAt = Date()
            self.lastSpeechAt = nil
            self.heardSpeech = false
            self.silenceTimer?.invalidate()
            self.silenceTimer = Timer.scheduledTimer(
                withTimeInterval: 0.18,
                repeats: true
            ) { [weak self] _ in
                self?.observeSpeechSilence()
            }
            recordButton?.title = "停止并转写"
            updateStatus("正在录音。说完停顿后会自动转写并保存。")
        } catch {
            updateStatus("录音启动失败：\(error.localizedDescription)")
        }
    }

    private func observeSpeechSilence() {
        guard let recorder, recorder.isRecording else {
            silenceTimer?.invalidate()
            silenceTimer = nil
            return
        }
        recorder.updateMeters()
        let now = Date()
        let elapsed = now.timeIntervalSince(recordingStartedAt ?? now)
        if recorder.averagePower(forChannel: 0) > -38 {
            heardSpeech = true
            lastSpeechAt = now
            return
        }
        if heardSpeech,
           elapsed >= 0.8,
           now.timeIntervalSince(lastSpeechAt ?? now) >= 1.25 {
            stopRecordingAndTranscribe()
            return
        }
        if !heardSpeech, elapsed >= 12 {
            stopRecordingAndTranscribe()
        }
    }

    private func stopRecordingAndTranscribe() {
        guard let recorder,
              let audioURL
        else {
            return
        }

        let duration = max(0, recorder.currentTime)
        silenceTimer?.invalidate()
        silenceTimer = nil
        recorder.stop()
        self.recorder = nil
        self.audioDurationSeconds = duration
        isTranscribing = true
        recordButton?.isEnabled = false
        recordButton?.title = "转写中..."
        let provider = selectedProvider()
        SpeechTranscriptionProvider.save(provider)
        updateStatus(provider == .appleSpeech ? "苹果转写中..." : "FunASR 转写中...")
        let audioNoteID = createPendingAudioNote(audioURL: audioURL, durationSeconds: duration, provider: provider.rawValue)
        latestAudioNoteID = audioNoteID

        if provider == .appleSpeech {
            transcribeWithAppleSpeech(audioURL: audioURL, audioNoteID: audioNoteID)
            return
        }

        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            guard let self else { return }
            do {
                let text = try self.transcribeWithFunASR(audioURL: audioURL)
                DispatchQueue.main.async {
                    self.latestAudioNoteID = audioNoteID
                    self.finishTranscription(text: text, provider: "funasr", displayProvider: "FunASR", audioNoteID: audioNoteID)
                }
            } catch {
                DispatchQueue.main.async {
                    self.latestAudioNoteID = audioNoteID
                    self.updateStatus("FunASR 转写失败，正在改用系统语音识别...")
                    self.transcribeWithAppleSpeech(audioURL: audioURL, audioNoteID: audioNoteID)
                }
            }
        }
    }

    private func audioNotesDirectory() throws -> URL {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first
            ?? FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library/Application Support", isDirectory: true)
        let directory = base.appendingPathComponent("SentenceReader/AudioNotes", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        return directory
    }

    private func appSupportDirectory() -> URL {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first
            ?? FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library/Application Support", isDirectory: true)
        return base.appendingPathComponent("SentenceReader", isDirectory: true)
    }

    private func runtimeConfigURL() -> URL {
        if let value = ProcessInfo.processInfo.environment["SENTENCE_READER_RUNTIME_CONFIG"],
           !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return URL(fileURLWithPath: (value as NSString).expandingTildeInPath)
        }
        return appSupportDirectory().appendingPathComponent("config/runtime_config.json")
    }

    private func runtimeConfigFunASRValue(_ key: String) -> String? {
        guard let data = try? Data(contentsOf: runtimeConfigURL()),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let funasr = object["funasr"] as? [String: Any],
              let value = funasr[key] as? String
        else {
            return nil
        }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private func configuredPath(userDefaultsKey: String, envKey: String, runtimeConfigKey: String, legacyDefault: String) -> (path: String, source: String) {
        if let value = UserDefaults.standard.string(forKey: userDefaultsKey),
           !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return (value, "user_defaults")
        }
        if let value = ProcessInfo.processInfo.environment[envKey],
           !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return (value, "environment")
        }
        if let value = runtimeConfigFunASRValue(runtimeConfigKey) {
            return (value, "runtime_config")
        }
        return (legacyDefault, "legacy_default")
    }

    private func resolvedFunASRPaths() -> FunASRPaths {
        let python = configuredPath(
            userDefaultsKey: funASRPythonDefaultsKey,
            envKey: funASRPythonEnvKey,
            runtimeConfigKey: "python",
            legacyDefault: funASRPythonDefaultPath
        )
        let worker = configuredPath(
            userDefaultsKey: funASRWorkerDefaultsKey,
            envKey: funASRWorkerEnvKey,
            runtimeConfigKey: "worker",
            legacyDefault: funASRWorkerDefaultPath
        )
        return FunASRPaths(
            python: URL(fileURLWithPath: (python.path as NSString).expandingTildeInPath),
            worker: URL(fileURLWithPath: (worker.path as NSString).expandingTildeInPath),
            source: "python=\(python.source), worker=\(worker.source)"
        )
    }

    private func createPendingAudioNote(audioURL: URL, durationSeconds: Double, provider: String) -> String? {
        guard let bookID else {
            return nil
        }
        return readerAPI.createAudioNote(
            bookID: bookID,
            audioPath: audioURL.path,
            provider: provider,
            status: "pending",
            transcript: nil,
            durationSeconds: durationSeconds,
            errorMessage: nil
        )
    }

    private func funASRServerURL(path: String) -> URL {
        URL(string: "http://127.0.0.1:\(funASRServerPort)\(path)")!
    }

    private func requestFunASRServer(path: String, method: String, payload: [String: Any]? = nil, timeout: TimeInterval) throws -> [String: Any] {
        var request = URLRequest(url: funASRServerURL(path: path))
        request.httpMethod = method
        request.timeoutInterval = timeout
        if let payload {
            request.httpBody = try JSONSerialization.data(withJSONObject: payload)
            request.setValue("application/json; charset=utf-8", forHTTPHeaderField: "Content-Type")
        }

        let semaphore = DispatchSemaphore(value: 0)
        var responseData: Data?
        var responseStatus = 0
        var responseError: Error?
        let task = URLSession.shared.dataTask(with: request) { data, response, error in
            responseData = data
            responseStatus = (response as? HTTPURLResponse)?.statusCode ?? 0
            responseError = error
            semaphore.signal()
        }
        task.resume()

        let waitResult = semaphore.wait(timeout: .now() + .milliseconds(Int((timeout + 0.5) * 1000)))
        if waitResult == .timedOut {
            task.cancel()
            throw NSError(domain: "SentenceReader.FunASRServer", code: 1, userInfo: [NSLocalizedDescriptionKey: "FunASR 后台服务请求超时"])
        }
        if let responseError {
            throw responseError
        }
        guard responseStatus == 200,
              let responseData,
              let object = try JSONSerialization.jsonObject(with: responseData) as? [String: Any]
        else {
            throw NSError(domain: "SentenceReader.FunASRServer", code: responseStatus, userInfo: [NSLocalizedDescriptionKey: "FunASR 后台服务响应不可用"])
        }
        return object
    }

    private func transcribeWithFunASRServer(audioURL: URL) throws -> String {
        let health = try requestFunASRServer(path: "/health", method: "GET", timeout: 1.0)
        guard health["ok"] as? Bool == true else {
            throw NSError(domain: "SentenceReader.FunASRServer", code: 2, userInfo: [NSLocalizedDescriptionKey: "FunASR 后台服务未就绪"])
        }

        let response = try requestFunASRServer(
            path: "/transcribe",
            method: "POST",
            payload: ["audio": audioURL.path],
            timeout: 120
        )
        guard response["ok"] as? Bool == true else {
            let detail = response["error"] as? String ?? "FunASR 后台服务转写失败"
            throw NSError(domain: "SentenceReader.FunASRServer", code: 3, userInfo: [NSLocalizedDescriptionKey: detail])
        }
        let text = (response["text"] as? String ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else {
            throw NSError(domain: "SentenceReader.FunASRServer", code: 4, userInfo: [NSLocalizedDescriptionKey: "FunASR 后台服务没有识别出文字"])
        }
        return text
    }

    private func transcribeWithFunASR(audioURL: URL) throws -> String {
        let funASRPaths = resolvedFunASRPaths()
        guard FileManager.default.isExecutableFile(atPath: funASRPaths.python.path),
              FileManager.default.fileExists(atPath: funASRPaths.worker.path)
        else {
            throw NSError(
                domain: "SentenceReader.FunASR",
                code: 1,
                userInfo: [
                    NSLocalizedDescriptionKey:
                        "FunASR Python 或 worker 不存在（\(funASRPaths.source)）。请通过 runtime_config.json、SENTENCE_READER_FUNASR_PYTHON/SENTENCE_READER_FUNASR_WORKER 或本机设置配置。"
                ]
            )
        }

        if let serverText = try? transcribeWithFunASRServer(audioURL: audioURL) {
            return serverText
        }

        let outputURL = audioURL.deletingPathExtension().appendingPathExtension("funasr.json")
        let process = Process()
        process.executableURL = funASRPaths.python
        process.arguments = [
            funASRPaths.worker.path,
            "--audio", audioURL.path,
            "--out", outputURL.path,
            "--model", "paraformer-zh",
            "--vad-model", "fsmn-vad",
            "--punc-model", "ct-punc",
            "--device", "cpu",
        ]

        let stderr = Pipe()
        process.standardError = stderr
        process.standardOutput = Pipe()
        try process.run()

        let deadline = Date().addingTimeInterval(120)
        while process.isRunning && Date() < deadline {
            Thread.sleep(forTimeInterval: 0.2)
        }
        if process.isRunning {
            process.terminate()
            throw NSError(domain: "SentenceReader.FunASR", code: 2, userInfo: [NSLocalizedDescriptionKey: "FunASR 转写超时"])
        }

        guard process.terminationStatus == 0 else {
            let data = stderr.fileHandleForReading.readDataToEndOfFile()
            let detail = String(data: data, encoding: .utf8) ?? "未知错误"
            throw NSError(domain: "SentenceReader.FunASR", code: Int(process.terminationStatus), userInfo: [NSLocalizedDescriptionKey: detail])
        }

        let data = try Data(contentsOf: outputURL)
        let json = try JSONSerialization.jsonObject(with: data)
        guard let items = json as? [[String: Any]] else {
            throw NSError(domain: "SentenceReader.FunASR", code: 3, userInfo: [NSLocalizedDescriptionKey: "FunASR 输出格式不可读"])
        }

        let text = items.compactMap { $0["text"] as? String }.joined(separator: " ").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else {
            throw NSError(domain: "SentenceReader.FunASR", code: 4, userInfo: [NSLocalizedDescriptionKey: "FunASR 没有识别出文字"])
        }
        return text
    }

    private func transcribeWithAppleSpeech(audioURL: URL, audioNoteID: String?) {
        SFSpeechRecognizer.requestAuthorization { [weak self] status in
            DispatchQueue.main.async {
                guard let self else { return }
                guard status == .authorized,
                      let recognizer = SFSpeechRecognizer(locale: Locale(identifier: "zh-CN")),
                      recognizer.isAvailable
                else {
                    self.failTranscription("苹果语音不可用", audioNoteID: audioNoteID)
                    return
                }

                let request = SFSpeechURLRecognitionRequest(url: audioURL)
                request.shouldReportPartialResults = false
                self.appleSpeechTask = recognizer.recognitionTask(with: request) { [weak self] result, error in
                    guard let self else { return }
                    if let result, result.isFinal {
                        self.finishTranscription(text: result.bestTranscription.formattedString, provider: "apple_speech", displayProvider: "系统语音识别", audioNoteID: audioNoteID)
                        return
                    }
                    if let error {
                        self.failTranscription("语音识别失败：\(error.localizedDescription)", audioNoteID: audioNoteID)
                    }
                }
            }
        }
    }

    private func finishTranscription(text: String, provider: String, displayProvider: String, audioNoteID: String?) {
        let cleaned = NoteTextNormalizer.normalized(text)
        guard !cleaned.isEmpty else {
            failTranscription("\(displayProvider) 没有识别出文字。", audioNoteID: audioNoteID)
            return
        }

        if let textView {
            let existing = textView.string.trimmingCharacters(in: .whitespacesAndNewlines)
            textView.string = existing.isEmpty ? cleaned : existing + "\n" + cleaned
        }
        if let audioNoteID {
            DispatchQueue.global(qos: .utility).async { [readerAPI] in
                _ = readerAPI.updateAudioNote(
                    audioNoteID: audioNoteID,
                    annotationID: nil,
                    provider: provider,
                    transcript: cleaned,
                    status: "transcribed",
                    errorMessage: nil
                )
            }
        }
        isTranscribing = false
        appleSpeechTask = nil
        recordButton?.isEnabled = true
        recordButton?.title = "开始录音"
        updateStatus("已插入并记录语音笔记（\(displayProvider)）。")
        onTranscriptionFinished?(audioNoteID)
    }

    private func failTranscription(_ message: String, audioNoteID: String? = nil) {
        if let audioNoteID {
            DispatchQueue.global(qos: .utility).async { [readerAPI] in
                _ = readerAPI.updateAudioNote(
                    audioNoteID: audioNoteID,
                    annotationID: nil,
                    provider: nil,
                    transcript: nil,
                    status: "failed",
                    errorMessage: message
                )
            }
        }
        isTranscribing = false
        appleSpeechTask = nil
        recordButton?.isEnabled = true
        recordButton?.title = "开始录音"
        updateStatus(message)
        onTranscriptionFinished?(audioNoteID)
    }

    private func updateStatus(_ text: String) {
        statusLabel?.stringValue = text
    }
}

final class ReaderAPIClient {
    static let runtimeContract = "click.reader_runtime.v1"
    static let minimumAPIRevision = 3

    static func configuredBaseURL() -> URL {
        let raw = ProcessInfo.processInfo.environment["SENTENCE_READER_API_BASE_URL"] ?? "http://127.0.0.1:18180"
        return URL(string: raw) ?? URL(string: "http://127.0.0.1:18180")!
    }

    private let baseURL = ReaderAPIClient.configuredBaseURL()
    private let timeout: TimeInterval = 2.0

    func health(requiredCapabilities: [String] = []) -> Bool {
        guard let json = request(method: "GET", path: "/health", body: nil) as? [String: Any] else {
            return false
        }
        guard json["ok"] as? Bool == true,
              let runtime = json["runtime"] as? [String: Any],
              runtime["contract"] as? String == Self.runtimeContract,
              let revision = runtime["api_revision"] as? Int,
              revision >= Self.minimumAPIRevision
        else {
            return false
        }
        let capabilities = Set(runtime["capabilities"] as? [String] ?? [])
        return requiredCapabilities.allSatisfy { capabilities.contains($0) }
    }

    func createBook(
        title: String,
        author: String?,
        bookHash: String,
        filePath: String?,
        sourceKind: String = "epub",
        fileHash: String? = nil,
        byteSize: Int? = nil
    ) -> String? {
        var body: [String: Any] = [
            "title": title,
            "source_kind": sourceKind,
            "book_hash": bookHash,
        ]
        if let author {
            body["author"] = author
        }
        if let filePath {
            body["file_path"] = filePath
        }
        if let fileHash {
            body["file_hash"] = fileHash
        }
        if let byteSize {
            body["byte_size"] = byteSize
        }
        return (request(method: "POST", path: "/books", body: body) as? [String: Any])?["id"] as? String
    }

    func listBooks() -> [[String: Any]] {
        request(method: "GET", path: "/books", body: nil) as? [[String: Any]] ?? []
    }

    func libraryDashboard() -> [String: Any]? {
        request(
            method: "GET",
            path: "/api/library/dashboard",
            body: nil,
            timeoutInterval: 12
        ) as? [String: Any]
    }

    func importBook(url: URL) -> [String: Any]? {
        guard let data = try? Data(contentsOf: url), !data.isEmpty else { return nil }
        let endpoint = baseURL.appendingPathComponent("api/library/import")
        var urlRequest = URLRequest(url: endpoint)
        urlRequest.httpMethod = "POST"
        urlRequest.timeoutInterval = 150
        urlRequest.setValue("application/json", forHTTPHeaderField: "Content-Type")
        let body: [String: Any] = [
            "filename": url.lastPathComponent,
            "content_base64": data.base64EncodedString(),
        ]
        urlRequest.httpBody = try? JSONSerialization.data(withJSONObject: body)
        let semaphore = DispatchSemaphore(value: 0)
        var result: [String: Any]?
        URLSession.shared.dataTask(with: urlRequest) { payload, response, _ in
            defer { semaphore.signal() }
            guard let http = response as? HTTPURLResponse,
                  (200..<300).contains(http.statusCode),
                  let payload
            else { return }
            result = try? JSONSerialization.jsonObject(with: payload) as? [String: Any]
        }.resume()
        _ = semaphore.wait(timeout: .now() + 151)
        return result
    }

    func getPosition(bookID: String) -> [String: Any]? {
        request(method: "GET", path: "/books/\(bookID)/position", body: nil) as? [String: Any]
    }

    func savePosition(
        bookID: String,
        chapterLocator: String,
        chapterIndex: Int,
        pageIndex: Int,
        totalPages: Int,
        pageRatio: Double,
        locator: [String: Any]? = nil
    ) {
        let body: [String: Any] = [
            "chapter_locator": chapterLocator,
            "page_index": pageIndex,
            "total_pages": totalPages,
            "page_ratio": pageRatio,
            "locator": locator ?? [
                "chapterIndex": chapterIndex,
                "chapterLocator": chapterLocator,
                "pageIndex": pageIndex,
                "totalPages": totalPages,
            ],
        ]
        _ = request(method: "PUT", path: "/books/\(bookID)/position", body: body)
    }

    func listAnnotations(bookID: String) -> [[String: Any]] {
        request(method: "GET", path: "/books/\(bookID)/annotations", body: nil) as? [[String: Any]] ?? []
    }

    func listAudioNotes(bookID: String) -> [[String: Any]] {
        request(method: "GET", path: "/books/\(bookID)/audio-notes", body: nil) as? [[String: Any]] ?? []
    }

    func getAudioNote(audioNoteID: String) -> [String: Any]? {
        request(method: "GET", path: "/audio-notes/\(audioNoteID)", body: nil) as? [String: Any]
    }

    func exportBook(bookID: String, outputDir: String?) -> [String: Any]? {
        var body: [String: Any] = ["include_json": true]
        if let outputDir {
            body["output_dir"] = outputDir
        }
        return request(method: "POST", path: "/books/\(bookID)/export", body: body) as? [String: Any]
    }

    func syncBookToHermes(bookID: String, outputDir: String?) -> [String: Any]? {
        var body: [String: Any] = ["include_red_highlights": true]
        if let outputDir {
            body["output_dir"] = outputDir
        }
        return request(method: "POST", path: "/books/\(bookID)/sync/hermes", body: body) as? [String: Any]
    }

    func cognitiveReviewQueue() -> [String: Any]? {
        request(method: "POST", path: "/cognitive/review-queue", body: ["limit": 100]) as? [String: Any]
    }

    func cognitiveDashboard() -> [String: Any]? {
        request(method: "POST", path: "/cognitive/dashboard", body: ["limit": 100, "history_limit": 20]) as? [String: Any]
    }

    func cognitiveOperatorDryRun() -> [String: Any]? {
        request(
            method: "POST",
            path: "/cognitive/operator/dry-run",
            body: ["all_ready": true, "allow_empty": true]
        ) as? [String: Any]
    }

    func cognitiveReviewItem() -> [String: Any]? {
        request(
            method: "POST",
            path: "/cognitive/review-item",
            body: ["prefer_statuses": ["ready_to_approve", "needs_review", "blocked"]]
        ) as? [String: Any]
    }

    func cognitiveApprove(candidateID: String, confirmationText: String) -> [String: Any]? {
        request(
            method: "POST",
            path: "/cognitive/operator/approve",
            body: [
                "candidate_intake_id": candidateID,
                "confirmation_text": confirmationText,
            ]
        ) as? [String: Any]
    }

    func createAudioNote(
        bookID: String,
        audioPath: String,
        provider: String,
        status: String,
        transcript: String?,
        durationSeconds: Double?,
        errorMessage: String?
    ) -> String? {
        var body: [String: Any] = [
            "book_id": bookID,
            "audio_path": audioPath,
            "provider": provider,
            "status": status,
        ]
        if let transcript {
            body["transcript"] = transcript
        }
        if let durationSeconds {
            body["duration_seconds"] = durationSeconds
        }
        if let errorMessage {
            body["error_message"] = errorMessage
        }
        return (request(method: "POST", path: "/audio-notes", body: body) as? [String: Any])?["id"] as? String
    }

    func updateAudioNote(
        audioNoteID: String,
        annotationID: String?,
        provider: String?,
        transcript: String?,
        status: String?,
        errorMessage: String?
    ) -> Bool {
        var body: [String: Any] = [:]
        if let annotationID {
            body["annotation_id"] = annotationID
        }
        if let provider {
            body["provider"] = provider
        }
        if let transcript {
            body["transcript"] = transcript
        }
        if let status {
            body["status"] = status
        }
        if let errorMessage {
            body["error_message"] = errorMessage
        }
        return request(method: "PATCH", path: "/audio-notes/\(audioNoteID)", body: body) != nil
    }

    func createAnnotation(
        bookID: String,
        kind: String,
        sourceText: String,
        noteText: String?,
        color: String?,
        chapterTitle: String?,
        chapterLocator: String,
        sentenceIndex: String,
        rangeLocator: [String: Any]? = nil,
        metadata: [String: Any]? = nil
    ) -> String? {
        var annotationMetadata: [String: Any] = [
            "source": "SentenceReaderNative",
            "sentenceIndex": sentenceIndex,
        ]
        if let metadata {
            for (key, value) in metadata {
                annotationMetadata[key] = value
            }
        }
        var body: [String: Any] = [
            "book_id": bookID,
            "kind": kind,
            "source_text": sourceText,
            "chapter_locator": chapterLocator,
            "range_locator": rangeLocator ?? [
                "chapterLocator": chapterLocator,
                "sentenceIndex": sentenceIndex,
            ],
            "metadata": annotationMetadata,
        ]
        if let noteText {
            body["note_text"] = noteText
        }
        if let color {
            body["color"] = color
        }
        if let chapterTitle {
            body["chapter_title"] = chapterTitle
        }
        return (request(method: "POST", path: "/annotations", body: body) as? [String: Any])?["id"] as? String
    }

    func deleteAnnotation(annotationID: String) -> Bool {
        request(method: "DELETE", path: "/annotations/\(annotationID)", body: nil) != nil
    }

    func updateAnnotation(annotationID: String, noteText: String?, color: String?) -> Bool {
        var body: [String: Any] = [:]
        if let noteText {
            body["note_text"] = noteText
        }
        if let color {
            body["color"] = color
        }
        return request(method: "PATCH", path: "/annotations/\(annotationID)", body: body) != nil
    }

    func lookupWord(bookID: String, word: String, sentenceIndex: String?, sentence: String? = nil) -> [String: Any]? {
        var components = URLComponents()
        components.path = "/books/\(bookID)/lookup"
        var queryItems = [URLQueryItem(name: "word", value: word)]
        if let sentenceIndex, !sentenceIndex.isEmpty {
            queryItems.append(URLQueryItem(name: "sentence_id", value: sentenceIndex))
        }
        if let sentence, !sentence.isEmpty {
            queryItems.append(URLQueryItem(name: "sentence", value: sentence))
        }
        components.queryItems = queryItems
        return request(method: "GET", path: components.string ?? "/books/\(bookID)/lookup", body: nil) as? [String: Any]
    }

    func lookupTTS(text: String, voice: String? = nil) -> URL? {
        let url = baseURL.appendingPathComponent("lookup/tts")
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.timeoutInterval = 20
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        var body: [String: Any] = ["text": text]
        if let voice, !voice.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            body["voice"] = voice
        }
        request.httpBody = try? JSONSerialization.data(withJSONObject: body)

        let semaphore = DispatchSemaphore(value: 0)
        var payload: [String: Any]?
        let task = URLSession.shared.dataTask(with: request) { data, response, _ in
            defer { semaphore.signal() }
            guard let http = response as? HTTPURLResponse,
                  (200..<300).contains(http.statusCode),
                  let data,
                  !data.isEmpty
            else {
                return
            }
            payload = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        }
        task.resume()
        _ = semaphore.wait(timeout: .now() + 21)

        guard payload?["ok"] as? Bool == true,
              let audioPath = payload?["audio_url"] as? String,
              !audioPath.isEmpty
        else {
            return nil
        }
        if let absolute = URL(string: audioPath), absolute.scheme != nil {
            return absolute
        }
        let relativePath = audioPath.hasPrefix("/") ? String(audioPath.dropFirst()) : audioPath
        return baseURL.appendingPathComponent(relativePath)
    }

    func lookupTTSData(text: String, voice: String? = nil) -> Data? {
        guard let audioURL = lookupTTS(text: text, voice: voice) else {
            return nil
        }
        return downloadLookupAudioData(from: audioURL)
    }

    func lookupCachedTTSData(text: String, voice: String? = nil) -> Data? {
        let url = baseURL.appendingPathComponent("lookup/tts/status")
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.timeoutInterval = 0.35
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        var body: [String: Any] = ["text": text]
        if let voice, !voice.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            body["voice"] = voice
        }
        request.httpBody = try? JSONSerialization.data(withJSONObject: body)

        let semaphore = DispatchSemaphore(value: 0)
        var payload: [String: Any]?
        let task = URLSession.shared.dataTask(with: request) { data, response, _ in
            defer { semaphore.signal() }
            guard let http = response as? HTTPURLResponse,
                  (200..<300).contains(http.statusCode),
                  let data,
                  !data.isEmpty
            else {
                return
            }
            payload = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        }
        task.resume()
        _ = semaphore.wait(timeout: .now() + 0.45)

        guard payload?["cached"] as? Bool == true,
              let audioPath = payload?["audio_url"] as? String,
              !audioPath.isEmpty
        else {
            return nil
        }
        if let absolute = URL(string: audioPath), absolute.scheme != nil {
            return downloadLookupAudioData(from: absolute)
        }
        let relativePath = audioPath.hasPrefix("/") ? String(audioPath.dropFirst()) : audioPath
        return downloadLookupAudioData(from: baseURL.appendingPathComponent(relativePath))
    }

    private func downloadLookupAudioData(from audioURL: URL) -> Data? {
        var request = URLRequest(url: audioURL)
        request.timeoutInterval = 20
        let semaphore = DispatchSemaphore(value: 0)
        var audioData: Data?
        let task = URLSession.shared.dataTask(with: request) { data, response, _ in
            defer { semaphore.signal() }
            guard let http = response as? HTTPURLResponse,
                  (200..<300).contains(http.statusCode),
                  let data,
                  !data.isEmpty
            else {
                return
            }
            audioData = data
        }
        task.resume()
        _ = semaphore.wait(timeout: .now() + 21)
        return audioData
    }

    func updateVocabItem(bookID: String, itemID: String, status: String) -> Bool {
        request(method: "PATCH", path: "/books/\(bookID)/vocab/\(itemID)", body: ["status": status]) != nil
    }

    func correctLookupMeaning(bookID: String, word: String, meaning: String, sentenceIndex: String?, sentence: String?) -> [String: Any]? {
        var body: [String: Any] = [
            "word": word,
            "meaning_zh": meaning,
        ]
        if let sentenceIndex, !sentenceIndex.isEmpty {
            body["sentence_id"] = sentenceIndex
        }
        if let sentence, !sentence.isEmpty {
            body["sentence"] = sentence
        }
        return request(method: "POST", path: "/books/\(bookID)/lookup-corrections", body: body) as? [String: Any]
    }

    func createLookupEvent(bookID: String, surface: String, lemma: String?, sentenceIndex: String?, sentence: String?) {
        var context: [String: Any] = [:]
        if let sentenceIndex, !sentenceIndex.isEmpty {
            context["sentenceIndex"] = sentenceIndex
        }
        if let sentence, !sentence.isEmpty {
            context["sentence"] = sentence
        }
        var body: [String: Any] = [
            "surface": surface,
            "event_kind": "lookup",
            "context": context,
        ]
        if let lemma, !lemma.isEmpty {
            body["lemma"] = lemma
        }
        _ = request(method: "POST", path: "/books/\(bookID)/lookup-events", body: body)
    }

    private func request(
        method: String,
        path: String,
        body: [String: Any]?,
        timeoutInterval: TimeInterval? = nil
    ) -> Any? {
        let effectiveTimeout = timeoutInterval ?? timeout
        let url: URL
        if path.contains("?"), let fullURL = URL(string: baseURL.absoluteString + path) {
            url = fullURL
        } else {
            url = baseURL.appendingPathComponent(String(path.dropFirst()))
        }
        var request = URLRequest(url: url)
        request.httpMethod = method
        request.timeoutInterval = effectiveTimeout
        if let body {
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.httpBody = try? JSONSerialization.data(withJSONObject: body)
        }

        let semaphore = DispatchSemaphore(value: 0)
        var output: Any?
        let task = URLSession.shared.dataTask(with: request) { data, response, _ in
            defer { semaphore.signal() }
            guard let http = response as? HTTPURLResponse,
                  (200..<300).contains(http.statusCode),
                  let data,
                  !data.isEmpty
            else {
                return
            }
            output = try? JSONSerialization.jsonObject(with: data)
        }
        task.resume()
        _ = semaphore.wait(timeout: .now() + effectiveTimeout + 0.5)
        return output
    }
}

private struct CognitiveDashboardDraftRow {
    let candidateID: String
    let draftID: String
    let status: String
    let bookTitle: String
    let qualityStatus: String
    let qualityScore: String
    let modelID: String
    let warnings: [String]
    let blockingReasons: [String]
    let draftPath: String

    init(payload: [String: Any]) {
        candidateID = Self.text(payload["candidate_intake_id"])
        draftID = Self.text(payload["draft_id"])
        status = Self.text(payload["status"])
        let title = Self.text(payload["book_title"])
        bookTitle = title.isEmpty ? (candidateID.isEmpty ? draftID : candidateID) : title
        qualityStatus = Self.text(payload["quality_status"])
        qualityScore = Self.text(payload["quality_score"])
        modelID = Self.text(payload["model_id"])
        warnings = Self.stringList(payload["warnings"])
        blockingReasons = Self.stringList(payload["blocking_reasons"])
        draftPath = Self.text(payload["draft_path"])
    }

    var statusTitle: String {
        switch status {
        case "ready_to_approve": return "可批准"
        case "needs_review": return "待审"
        case "blocked": return "阻塞"
        case "already_promoted": return "已入库"
        default: return status.isEmpty ? "未知" : status
        }
    }

    var qualityTitle: String {
        let score = qualityScore.isEmpty ? "-" : qualityScore
        return "\(qualityStatus.isEmpty ? "unknown" : qualityStatus) / \(score)"
    }

    var issueTitle: String {
        let issues = blockingReasons + warnings
        return issues.isEmpty ? "无" : issues.prefix(3).joined(separator: "；")
    }

    private static func text(_ value: Any?) -> String {
        if let text = value as? String {
            return text
        }
        if let number = value as? NSNumber {
            return number.stringValue
        }
        if let value {
            return "\(value)"
        }
        return ""
    }

    private static func stringList(_ value: Any?) -> [String] {
        guard let values = value as? [Any] else {
            return []
        }
        return values.map { text($0) }.filter { !$0.isEmpty }
    }
}

private struct CognitiveDashboardHistoryRow {
    let status: String
    let approved: String
    let dryRun: String
    let selectedCount: String
    let rebuildOK: String
    let qualityOK: String
    let qualitySkipped: String
    let reportPath: String
    let rollbackPath: String

    init(payload: [String: Any]) {
        status = Self.text(payload["status"])
        approved = Self.text(payload["approved"])
        dryRun = Self.text(payload["dry_run"])
        selectedCount = Self.text(payload["selected_count"])
        reportPath = Self.text(payload["report_path"])
        rollbackPath = Self.text(payload["rollback_manifest_path"])
        let rebuild = payload["active_pack_rebuild"] as? [String: Any] ?? [:]
        let quality = payload["quality_gate"] as? [String: Any] ?? [:]
        rebuildOK = Self.text(rebuild["ok"])
        qualityOK = Self.text(quality["ok"])
        qualitySkipped = Self.text(quality["skipped"])
    }

    var summary: String {
        [
            "status=\(status.isEmpty ? "unknown" : status)",
            "approved=\(approved.isEmpty ? "-" : approved)",
            "dry_run=\(dryRun.isEmpty ? "-" : dryRun)",
            "selected=\(selectedCount.isEmpty ? "0" : selectedCount)",
            "rebuild=\(rebuildOK.isEmpty ? "-" : rebuildOK)",
            "quality=\(qualityOK.isEmpty ? "-" : qualityOK)",
            "skipped=\(qualitySkipped.isEmpty ? "-" : qualitySkipped)",
            "rollback=\(rollbackPath.isEmpty ? "-" : rollbackPath)",
        ].joined(separator: " · ")
    }

    private static func text(_ value: Any?) -> String {
        if let text = value as? String {
            return text
        }
        if let number = value as? NSNumber {
            return number.stringValue
        }
        if let value {
            return "\(value)"
        }
        return ""
    }
}

private final class CognitiveDashboardWindowController: NSWindowController, NSTableViewDataSource, NSTableViewDelegate {
    private let dashboard: [String: Any]
    private let openPath: (String) -> Void
    private let allRows: [CognitiveDashboardDraftRow]
    private var filteredRows: [CognitiveDashboardDraftRow]
    private let historyRows: [CognitiveDashboardHistoryRow]
    private let tableView = NSTableView()
    private let statusFilterControl = NSSegmentedControl(labels: ["全部", "可批准", "待审", "阻塞", "已入库"], trackingMode: .selectOne, target: nil, action: nil)
    private let summaryLabel = NSTextField(labelWithString: "")
    private let approvalHistoryTextView = NSTextView()
    private let dashboardMarkdownPath: String

    init(dashboard: [String: Any], openPath: @escaping (String) -> Void) {
        self.dashboard = dashboard
        self.openPath = openPath
        let items = dashboard["items"] as? [[String: Any]] ?? []
        self.allRows = items.map(CognitiveDashboardDraftRow.init(payload:))
        self.filteredRows = self.allRows
        let history = dashboard["approval_history"] as? [[String: Any]] ?? []
        self.historyRows = history.map(CognitiveDashboardHistoryRow.init(payload:))
        self.dashboardMarkdownPath = Self.text(dashboard["markdown_path"])

        let window = NSWindow(
            contentRect: NSRect(x: 120, y: 120, width: 980, height: 620),
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered,
            defer: false
        )
        window.title = "认知审核台"
        super.init(window: window)
        window.contentView = makeContentView()
        updateSummary()
        updateApprovalHistory()
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    private func makeContentView() -> NSView {
        let root = NSView()
        root.wantsLayer = true
        root.layer?.backgroundColor = NSColor.windowBackgroundColor.cgColor

        let title = NSTextField(labelWithString: "认知审核台")
        title.font = NSFont(name: "Microsoft YaHei", size: 18) ?? NSFont.systemFont(ofSize: 18, weight: .semibold)

        summaryLabel.font = NSFont(name: "Microsoft YaHei", size: 12) ?? NSFont.systemFont(ofSize: 12)
        summaryLabel.textColor = .secondaryLabelColor
        summaryLabel.lineBreakMode = .byTruncatingTail

        statusFilterControl.target = self
        statusFilterControl.action = #selector(filterChanged(_:))
        statusFilterControl.selectedSegment = 0

        tableView.delegate = self
        tableView.dataSource = self
        tableView.rowHeight = 42
        tableView.usesAlternatingRowBackgroundColors = true
        addColumn(identifier: "status", title: "状态", width: 86)
        addColumn(identifier: "title", title: "书/候选", width: 260)
        addColumn(identifier: "quality", title: "质量", width: 120)
        addColumn(identifier: "model", title: "模型", width: 180)
        addColumn(identifier: "issues", title: "问题", width: 300)

        let tableScroll = NSScrollView()
        tableScroll.documentView = tableView
        tableScroll.hasVerticalScroller = true
        tableScroll.borderType = .bezelBorder

        let historyTitle = NSTextField(labelWithString: "审批历史")
        historyTitle.font = NSFont(name: "Microsoft YaHei", size: 13) ?? NSFont.systemFont(ofSize: 13, weight: .semibold)

        approvalHistoryTextView.isEditable = false
        approvalHistoryTextView.isSelectable = true
        approvalHistoryTextView.font = NSFont.monospacedSystemFont(ofSize: 11, weight: .regular)
        approvalHistoryTextView.textContainerInset = NSSize(width: 8, height: 8)

        let historyScroll = NSScrollView()
        historyScroll.documentView = approvalHistoryTextView
        historyScroll.hasVerticalScroller = true
        historyScroll.borderType = .bezelBorder

        let openMarkdownButton = NSButton(title: "打开Markdown仪表盘", target: self, action: #selector(openMarkdownDashboard(_:)))
        openMarkdownButton.bezelStyle = .rounded

        let openDraftButton = NSButton(title: "打开所选草稿", target: self, action: #selector(openSelectedDraft(_:)))
        openDraftButton.bezelStyle = .rounded

        let closeButton = NSButton(title: "关闭", target: self, action: #selector(closeWindow(_:)))
        closeButton.bezelStyle = .rounded

        let topStack = NSStackView(views: [title, NSView(), statusFilterControl])
        topStack.orientation = .horizontal
        topStack.alignment = .centerY
        topStack.spacing = 12

        let buttonStack = NSStackView(views: [openMarkdownButton, openDraftButton, NSView(), closeButton])
        buttonStack.orientation = .horizontal
        buttonStack.alignment = .centerY
        buttonStack.spacing = 10

        let stack = NSStackView(views: [topStack, summaryLabel, tableScroll, historyTitle, historyScroll, buttonStack])
        stack.orientation = .vertical
        stack.alignment = .leading
        stack.spacing = 10

        [stack, topStack, summaryLabel, tableScroll, historyTitle, historyScroll, buttonStack].forEach {
            $0.translatesAutoresizingMaskIntoConstraints = false
        }
        root.addSubview(stack)

        NSLayoutConstraint.activate([
            stack.topAnchor.constraint(equalTo: root.topAnchor, constant: 16),
            stack.leadingAnchor.constraint(equalTo: root.leadingAnchor, constant: 16),
            stack.trailingAnchor.constraint(equalTo: root.trailingAnchor, constant: -16),
            stack.bottomAnchor.constraint(equalTo: root.bottomAnchor, constant: -16),
            topStack.widthAnchor.constraint(equalTo: stack.widthAnchor),
            summaryLabel.widthAnchor.constraint(equalTo: stack.widthAnchor),
            tableScroll.widthAnchor.constraint(equalTo: stack.widthAnchor),
            tableScroll.heightAnchor.constraint(greaterThanOrEqualToConstant: 280),
            historyTitle.widthAnchor.constraint(equalTo: stack.widthAnchor),
            historyScroll.widthAnchor.constraint(equalTo: stack.widthAnchor),
            historyScroll.heightAnchor.constraint(equalToConstant: 120),
            buttonStack.widthAnchor.constraint(equalTo: stack.widthAnchor),
        ])

        return root
    }

    private func addColumn(identifier: String, title: String, width: CGFloat) {
        let column = NSTableColumn(identifier: NSUserInterfaceItemIdentifier(identifier))
        column.title = title
        column.width = width
        column.minWidth = 72
        column.resizingMask = .autoresizingMask
        tableView.addTableColumn(column)
    }

    private func updateSummary() {
        let counts = dashboard["counts"] as? [String: Any] ?? [:]
        let ready = Self.text(counts["ready_to_approve"])
        let needsReview = Self.text(counts["needs_review"])
        let blocked = Self.text(counts["blocked"])
        let alreadyPromoted = Self.text(counts["already_promoted"])
        let total = Self.text(dashboard["draft_count"])
        summaryLabel.stringValue = "草稿 \(total.isEmpty ? "0" : total) · 可批准 \(ready.isEmpty ? "0" : ready) · 待审 \(needsReview.isEmpty ? "0" : needsReview) · 阻塞 \(blocked.isEmpty ? "0" : blocked) · 已入库 \(alreadyPromoted.isEmpty ? "0" : alreadyPromoted)"
    }

    private func updateApprovalHistory() {
        guard !historyRows.isEmpty else {
            approvalHistoryTextView.string = "暂无审批历史"
            return
        }
        approvalHistoryTextView.string = historyRows.prefix(12).map { $0.summary }.joined(separator: "\n")
    }

    @objc private func filterChanged(_ sender: NSSegmentedControl) {
        let selectedStatus: String?
        switch sender.selectedSegment {
        case 1: selectedStatus = "ready_to_approve"
        case 2: selectedStatus = "needs_review"
        case 3: selectedStatus = "blocked"
        case 4: selectedStatus = "already_promoted"
        default: selectedStatus = nil
        }
        if let selectedStatus {
            filteredRows = allRows.filter { $0.status == selectedStatus }
        } else {
            filteredRows = allRows
        }
        tableView.reloadData()
    }

    @objc private func openMarkdownDashboard(_ sender: Any?) {
        guard !dashboardMarkdownPath.isEmpty else {
            NSSound.beep()
            return
        }
        openPath(dashboardMarkdownPath)
    }

    @objc private func openSelectedDraft(_ sender: Any?) {
        let row = tableView.selectedRow
        guard filteredRows.indices.contains(row),
              !filteredRows[row].draftPath.isEmpty
        else {
            NSSound.beep()
            return
        }
        openPath(filteredRows[row].draftPath)
    }

    @objc private func closeWindow(_ sender: Any?) {
        close()
    }

    func numberOfRows(in tableView: NSTableView) -> Int {
        filteredRows.count
    }

    func tableView(_ tableView: NSTableView, heightOfRow row: Int) -> CGFloat {
        42
    }

    func tableView(_ tableView: NSTableView, viewFor tableColumn: NSTableColumn?, row: Int) -> NSView? {
        guard filteredRows.indices.contains(row),
              let identifier = tableColumn?.identifier.rawValue
        else {
            return nil
        }
        let item = filteredRows[row]
        let value: String
        switch identifier {
        case "status": value = item.statusTitle
        case "title": value = item.bookTitle
        case "quality": value = item.qualityTitle
        case "model": value = item.modelID.isEmpty ? "-" : item.modelID
        case "issues": value = item.issueTitle
        default: value = ""
        }
        let label = NSTextField(labelWithString: value)
        label.font = NSFont(name: "Microsoft YaHei", size: 12) ?? NSFont.systemFont(ofSize: 12)
        label.lineBreakMode = .byTruncatingTail
        label.maximumNumberOfLines = identifier == "issues" ? 2 : 1
        if identifier == "status" {
            label.textColor = statusColor(for: item.status)
        }
        return label
    }

    private func statusColor(for status: String) -> NSColor {
        switch status {
        case "ready_to_approve": return .systemGreen
        case "needs_review": return .systemOrange
        case "blocked": return .systemRed
        case "already_promoted": return .systemBlue
        default: return .secondaryLabelColor
        }
    }

    private static func text(_ value: Any?) -> String {
        if let text = value as? String {
            return text
        }
        if let number = value as? NSNumber {
            return number.stringValue
        }
        if let value {
            return "\(value)"
        }
        return ""
    }
}

private enum ClickTTSGate0Contract {
    static let disclosureRevision = "edge-online-2026-07-v1"
    static let disclosureDefaultsKey = "Click.EdgeTTS.Disclosure.edge-online-2026-07-v1"
    static let expectedRuntimeID = "click-edge-tts-cpython311-macos-arm64-v1"
    static let expectedPythonVersion = "3.11.15"
    static let expectedEdgeTTSVersion = "7.2.8"
    static let helperRelativePath = "helper/click_tts_helper.py"
    static let pythonRelativePath = "python/bin/python3.11"
    static let cacheNamespace = "reading-v2/probe-v1"
    static let clientVersion = "click-gate0-v1"
    static let defaultFixtureID = "gate0-probe-v1"

    static let defaultCacheContext: [String: String] = [
        "book_id": "gate0-probe",
        "fixture_id": defaultFixtureID,
        "chapter_locator": "probe-1",
        "locator_range": "0:0",
        "client_version": clientVersion,
        "voice_cache_epoch": "1",
        "prosody_revision": "1",
        "normalizer_revision": "1",
        "engine_revision": "1",
    ]
    static let cacheContext = defaultCacheContext

    static func cacheContext(
        fixtureID: String,
        chapterLocator: String,
        locatorRange: String
    ) -> [String: String] {
        var context = defaultCacheContext
        context["fixture_id"] = fixtureID
        context["chapter_locator"] = chapterLocator
        context["locator_range"] = locatorRange
        return context
    }

    static let synthesis: [String: String] = [
        "rate": "+0%",
        "volume": "+0%",
        "pitch": "+0Hz",
        "boundary": "SentenceBoundary",
    ]

    static var cacheRoot: URL {
        let base = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        ).first ?? FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support", isDirectory: true)
        return base
            .appendingPathComponent("Click", isDirectory: true)
            .appendingPathComponent("ReaderTTS", isDirectory: true)
            .appendingPathComponent(cacheNamespace, isDirectory: true)
    }

    static func sha256(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    static func sha256File(
        _ url: URL,
        checkpoint: (() throws -> Void)? = nil
    ) throws -> String {
        let handle = try FileHandle(forReadingFrom: url)
        defer { try? handle.close() }
        var hasher = SHA256()
        while true {
            try checkpoint?()
            let data = try handle.read(upToCount: 1024 * 1024) ?? Data()
            if data.isEmpty {
                break
            }
            hasher.update(data: data)
        }
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }

    static func canonicalJSON(_ object: [String: String]) throws -> Data {
        try JSONSerialization.data(
            withJSONObject: object,
            options: [.sortedKeys, .withoutEscapingSlashes]
        )
    }

    static func cacheIdentity(
        text: String,
        voice: String,
        cacheContext: [String: String] = defaultCacheContext,
        synthesisSettings: [String: String] = synthesis
    ) throws -> (key: String, textHash: String) {
        let textHash = sha256(Data(text.utf8))
        let generationParamsHash = sha256(
            try canonicalJSON(synthesisSettings)
        )
        var material = cacheContext
        material["normalized_text_hash"] = textHash
        material["backend_id"] = "edge_online"
        material["voice_id"] = voice
        material["edge_tts_client_version"] = expectedEdgeTTSVersion
        material["generation_params_hash"] = generationParamsHash
        return (sha256(try canonicalJSON(material)), textHash)
    }

    static func cacheURLs(for key: String) -> (audio: URL, metadata: URL, manifest: URL) {
        let shard = cacheRoot.appendingPathComponent(String(key.prefix(2)), isDirectory: true)
        return (
            shard.appendingPathComponent("\(key).mp3"),
            shard.appendingPathComponent("\(key).boundaries.json"),
            shard.appendingPathComponent("\(key).manifest.json")
        )
    }

    static func validateGoldenVector() -> Bool {
        guard let identity = try? cacheIdentity(
            text: "Click Gate 0 中英混排 test.",
            voice: "zh-CN-YunjianNeural"
        ) else {
            return false
        }
        return identity.textHash == "becee1b4696910aeff85a1fee3b6b0036f1d5388bd97d099ed3ce37784e341fd"
            && identity.key == "dc04ad55f650b91ac50dee394049a6a23fece10f23bc708f574c90fdf8731cd8"
    }
}

private struct ClickTTSGate0CachedArtifact {
    let cacheKey: String
    let audioURL: URL
    let metadataURL: URL
    let manifestURL: URL
    let source: String
    let boundaryCount: Int
    let generationMetrics: ClickTTSGate0GenerationMetrics
}

private enum ClickTTSGate0Cache {
    private static func isDirectory(
        _ url: URL,
        privatePermissions: Bool
    ) -> Bool {
        guard let values = try? url.resourceValues(
            forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
        ),
        values.isDirectory == true,
        values.isSymbolicLink != true
        else {
            return false
        }
        guard privatePermissions else {
            return true
        }
        guard let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
              let permissions = attributes[.posixPermissions] as? NSNumber
        else {
            return false
        }
        return permissions.intValue & 0o777 == 0o700
    }

    private static func privateCacheHierarchy(shard: URL) -> Bool {
        let root = ClickTTSGate0Contract.cacheRoot.standardizedFileURL
        let appSupport = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        ).first?.standardizedFileURL
        guard let appSupport,
              shard.standardizedFileURL.path.hasPrefix(root.path + "/"),
              isDirectory(appSupport, privatePermissions: false)
        else {
            return false
        }
        let privateDirectories = [
            appSupport.appendingPathComponent("Click", isDirectory: true),
            appSupport.appendingPathComponent("Click/ReaderTTS", isDirectory: true),
            appSupport.appendingPathComponent("Click/ReaderTTS/reading-v2", isDirectory: true),
            root,
            shard.standardizedFileURL,
        ]
        return privateDirectories.allSatisfy {
            isDirectory($0, privatePermissions: true)
        }
    }

    private static func isPrivateRegularFile(_ url: URL) -> Bool {
        guard let values = try? url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        ),
        values.isRegularFile == true,
        values.isSymbolicLink != true,
        let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
        let permissions = attributes[.posixPermissions] as? NSNumber
        else {
            return false
        }
        return permissions.intValue & 0o777 == 0o600
    }

    private static func looksLikeMP3(_ url: URL) -> Bool {
        guard let handle = try? FileHandle(forReadingFrom: url) else {
            return false
        }
        defer { try? handle.close() }
        let data = (try? handle.read(upToCount: 4096)) ?? nil
        guard let data, data.count >= 128 else {
            return false
        }
        if data.starts(with: Data("ID3".utf8)) {
            return true
        }
        let bytes = [UInt8](data)
        guard bytes.count > 1 else {
            return false
        }
        for index in 0..<(bytes.count - 1) {
            if bytes[index] == 0xFF && (bytes[index + 1] & 0xE0) == 0xE0 {
                return true
            }
        }
        return false
    }

    private static func validBoundaries(_ value: Any) -> Int? {
        guard let rows = value as? [[String: Any]], !rows.isEmpty else {
            return nil
        }
        func strictInteger(_ value: Any?) -> Int? {
            guard let number = value as? NSNumber,
                  CFGetTypeID(number) != CFBooleanGetTypeID(),
                  number.doubleValue.isFinite,
                  number.doubleValue.rounded(.towardZero) == number.doubleValue,
                  number.doubleValue >= 0,
                  number.doubleValue <= 9_000_000_000_000
            else {
                return nil
            }
            return number.intValue
        }
        var previousOffset = -1
        for (ordinal, row) in rows.enumerated() {
            guard row.count == 4,
                  strictInteger(row["ordinal"]) == ordinal,
                  let type = row["type"] as? String,
                  ["SentenceBoundary", "WordBoundary"].contains(type),
                  let offset = strictInteger(row["offset"]),
                  let duration = strictInteger(row["duration"]),
                  offset >= previousOffset,
                  duration >= 0
            else {
                return nil
            }
            previousOffset = offset
        }
        return rows.count
    }

    static func load(
        text: String,
        voice: String,
        cacheContext: [String: String] =
            ClickTTSGate0Contract.defaultCacheContext,
        synthesisSettings: [String: String] =
            ClickTTSGate0Contract.synthesis
    ) -> ClickTTSGate0CachedArtifact? {
        guard ClickTTSGate0Contract.validateGoldenVector(),
              let identity = try? ClickTTSGate0Contract.cacheIdentity(
                text: text,
                voice: voice,
                cacheContext: cacheContext,
                synthesisSettings: synthesisSettings
              )
        else {
            return nil
        }
        let urls = ClickTTSGate0Contract.cacheURLs(for: identity.key)
        let shard = urls.manifest.deletingLastPathComponent()
        guard [urls.audio, urls.metadata, urls.manifest].allSatisfy(isPrivateRegularFile),
              privateCacheHierarchy(shard: shard),
              let manifestSize = try? urls.manifest.resourceValues(
                forKeys: [.fileSizeKey]
              ).fileSize,
              manifestSize > 0,
              manifestSize <= 128 * 1024,
              let metadataSize = try? urls.metadata.resourceValues(
                forKeys: [.fileSizeKey]
              ).fileSize,
              metadataSize > 0,
              metadataSize <= 8 * 1024 * 1024,
              let audioSize = try? urls.audio.resourceValues(
                forKeys: [.fileSizeKey]
              ).fileSize,
              audioSize >= 128,
              audioSize <= 256 * 1024 * 1024,
              let manifestData = try? Data(
                contentsOf: urls.manifest,
                options: [.mappedIfSafe]
              ),
              let manifest = try? JSONSerialization.jsonObject(with: manifestData) as? [String: Any],
              let metadataData = try? Data(
                contentsOf: urls.metadata,
                options: [.mappedIfSafe]
              ),
              let metadata = try? JSONSerialization.jsonObject(with: metadataData),
              let boundaryCount = validBoundaries(metadata),
              looksLikeMP3(urls.audio),
              manifest["schema_version"] as? Int == 1,
              manifest["cache_key"] as? String == identity.key,
              manifest["backend_id"] as? String == "edge_online",
              manifest["voice"] as? String == voice,
              manifest["text_sha256"] as? String == identity.textHash,
              manifest["fixture_id"] as? String == cacheContext["fixture_id"],
              manifest["chapter_locator"] as? String == cacheContext["chapter_locator"],
              manifest["locator_range"] as? String == cacheContext["locator_range"],
              manifest["edge_tts_version"] as? String == ClickTTSGate0Contract.expectedEdgeTTSVersion,
              manifest["audio_file"] as? String == urls.audio.lastPathComponent,
              manifest["metadata_file"] as? String == urls.metadata.lastPathComponent,
              (manifest["audio_bytes"] as? NSNumber)?.intValue == audioSize,
              (manifest["boundary_count"] as? NSNumber)?.intValue == boundaryCount,
              manifest["audio_sha256"] as? String == (try? ClickTTSGate0Contract.sha256File(urls.audio)),
              manifest["metadata_sha256"] as? String == (try? ClickTTSGate0Contract.sha256File(urls.metadata))
        else {
            return nil
        }
        let generationMetrics = ClickTTSGate0GenerationMetrics(result: manifest)
        guard let attemptCount = generationMetrics.attemptCount,
              (1...3).contains(attemptCount),
              let synthesisElapsedMS = generationMetrics.synthesisElapsedMS,
              let audioDurationMS = generationMetrics.audioDurationMS,
              audioDurationMS > 0,
              let synthesisRTF = generationMetrics.synthesisRTF,
              abs(synthesisRTF - (synthesisElapsedMS / audioDurationMS)) <= 0.000_001
        else {
            return nil
        }
        return ClickTTSGate0CachedArtifact(
            cacheKey: identity.key,
            audioURL: urls.audio,
            metadataURL: urls.metadata,
            manifestURL: urls.manifest,
            source: "cache",
            boundaryCount: boundaryCount,
            generationMetrics: generationMetrics
        )
    }

    @discardableResult
    static func evict(_ artifact: ClickTTSGate0CachedArtifact) -> Bool {
        let expected = ClickTTSGate0Contract.cacheURLs(for: artifact.cacheKey)
        let expectedURLs = [expected.audio, expected.metadata, expected.manifest]
        let artifactURLs = [
            artifact.audioURL,
            artifact.metadataURL,
            artifact.manifestURL,
        ]
        guard zip(expectedURLs, artifactURLs).allSatisfy({
            $0.0.standardizedFileURL == $0.1.standardizedFileURL
        }),
        privateCacheHierarchy(shard: expected.manifest.deletingLastPathComponent()),
        artifactURLs.allSatisfy(isPrivateRegularFile)
        else {
            return false
        }
        var removedAll = true
        for url in artifactURLs {
            do {
                try FileManager.default.removeItem(at: url)
            } catch {
                removedAll = false
            }
        }
        return removedAll
    }

    static func cleanupPartials(ownedBy helperPID: Int32) {
        let root = ClickTTSGate0Contract.cacheRoot
        guard helperPID > 0,
              isDirectory(root, privatePermissions: true),
              let shards = try? FileManager.default.contentsOfDirectory(
                at: root,
                includingPropertiesForKeys: [.isDirectoryKey, .isSymbolicLinkKey],
                options: [.skipsHiddenFiles]
              )
        else {
            return
        }
        let pattern = "^[0-9a-f]{64}\\.(?:mp3|boundaries\\.json|manifest\\.json)"
            + "\\.partial\\.\(helperPID)\\.[0-9a-f]{32}$"
        for shard in shards {
            guard shard.lastPathComponent.range(
                of: "^[0-9a-f]{2}$",
                options: .regularExpression
            ) != nil,
            privateCacheHierarchy(shard: shard),
            let files = try? FileManager.default.contentsOfDirectory(
                at: shard,
                includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
                options: [.skipsHiddenFiles]
            )
            else {
                continue
            }
            for url in files {
                guard url.lastPathComponent.range(
                    of: pattern,
                    options: .regularExpression
                ) != nil,
                let values = try? url.resourceValues(
                    forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                ),
                values.isRegularFile == true,
                values.isSymbolicLink != true
                else {
                    continue
                }
                try? FileManager.default.removeItem(at: url)
            }
        }
    }
}

private struct ClickTTSGate0RuntimeLocation {
    let root: URL
    let python: URL
    let helper: URL
    let runtimeID: String
}

private enum ClickTTSGate0RuntimeVerifier {
    private struct FileStamp: Equatable {
        let relativePath: String
        let size: Int
        let mode: Int
        let inode: UInt64
        let modificationTime: TimeInterval
    }

    private struct ProcessVerification {
        let rootPath: String
        let manifestHash: String
        let manifestStamp: FileStamp
        let fileStamps: [String: FileStamp]
        let declared: Set<String>
    }

    private static let processCacheLock = NSLock()
    private static var processVerification: ProcessVerification?
    private static let fullVerificationTimeLimit: TimeInterval = 15

    private static func fail(_ message: String) -> NSError {
        NSError(
            domain: "Click.EdgeTTS.Runtime",
            code: 1,
            userInfo: [NSLocalizedDescriptionKey: message]
        )
    }

    private static func checkpoint(
        _ externalCheck: () throws -> Void,
        deadline: TimeInterval
    ) throws {
        try externalCheck()
        guard ProcessInfo.processInfo.systemUptime <= deadline else {
            throw fail("私有语音运行时完整性校验超过 15 秒，已停止以避免持续占用 CPU")
        }
    }

    private static func stamp(
        _ url: URL,
        relativePath: String
    ) throws -> FileStamp {
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true,
              values.isSymbolicLink != true
        else {
            throw fail("运行时文件类型不安全：\(relativePath)")
        }
        let attributes = try FileManager.default.attributesOfItem(atPath: url.path)
        guard let size = (attributes[.size] as? NSNumber)?.intValue,
              let permissions = (attributes[.posixPermissions] as? NSNumber)?.intValue,
              let inode = (attributes[.systemFileNumber] as? NSNumber)?.uint64Value,
              let modificationDate = attributes[.modificationDate] as? Date
        else {
            throw fail("无法读取运行时文件属性：\(relativePath)")
        }
        return FileStamp(
            relativePath: relativePath,
            size: size,
            mode: permissions & 0o7777,
            inode: inode,
            modificationTime: modificationDate.timeIntervalSince1970
        )
    }

    private static func verifiedLocation(root: URL) throws -> ClickTTSGate0RuntimeLocation {
        let python = root.appendingPathComponent(ClickTTSGate0Contract.pythonRelativePath)
        let helper = root.appendingPathComponent(ClickTTSGate0Contract.helperRelativePath)
        guard FileManager.default.isExecutableFile(atPath: python.path),
              FileManager.default.fileExists(atPath: helper.path)
        else {
            throw fail("Click 私有语音运行时入口缺失")
        }
        return ClickTTSGate0RuntimeLocation(
            root: root,
            python: python,
            helper: helper,
            runtimeID: ClickTTSGate0Contract.expectedRuntimeID
        )
    }

    private static func verifyCachedProcessRuntime(
        _ cached: ProcessVerification,
        root: URL,
        manifestURL: URL,
        manifestData: Data,
        externalCheck: () throws -> Void,
        deadline: TimeInterval
    ) throws -> ClickTTSGate0RuntimeLocation {
        guard cached.rootPath == root.path,
              ClickTTSGate0Contract.sha256(manifestData) == cached.manifestHash,
              try stamp(
                manifestURL,
                relativePath: "runtime-manifest.json"
              ) == cached.manifestStamp
        else {
            throw fail("Click 运行期间私有语音清单发生变化，已拒绝继续启动 helper")
        }

        for relative in cached.declared.sorted() {
            try checkpoint(externalCheck, deadline: deadline)
            guard let expected = cached.fileStamps[relative] else {
                throw fail("进程内运行时快照不完整")
            }
            let fileURL = root.appendingPathComponent(relative).standardizedFileURL
            guard fileURL.path.hasPrefix(root.path + "/"),
                  try stamp(fileURL, relativePath: relative) == expected
            else {
                throw fail("Click 运行期间私有语音文件发生变化：\(relative)")
            }
        }

        guard let enumerator = FileManager.default.enumerator(
            at: root,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
            options: []
        ) else {
            throw fail("无法枚举语音运行时")
        }
        var actual = Set<String>()
        for case let url as URL in enumerator {
            try checkpoint(externalCheck, deadline: deadline)
            let values = try url.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            )
            if values.isSymbolicLink == true {
                throw fail("运行时包含符号链接：\(url.lastPathComponent)")
            }
            if values.isRegularFile == true {
                let canonicalURL = url
                    .resolvingSymlinksInPath()
                    .standardizedFileURL
                guard canonicalURL.path.hasPrefix(root.path + "/") else {
                    throw fail("运行时文件越出私有目录：\(url.lastPathComponent)")
                }
                let relative = String(canonicalURL.path.dropFirst(root.path.count + 1))
                if relative != "runtime-manifest.json" {
                    actual.insert(relative)
                }
            }
        }
        guard actual == cached.declared else {
            throw fail("Click 运行期间私有语音文件树发生变化")
        }
        return try verifiedLocation(root: root)
    }

    static func locateAndVerify(
        externalCheck: @escaping () throws -> Void = {}
    ) throws -> ClickTTSGate0RuntimeLocation {
        let deadline = ProcessInfo.processInfo.systemUptime + fullVerificationTimeLimit
        try checkpoint(externalCheck, deadline: deadline)
        guard ClickTTSGate0Contract.validateGoldenVector() else {
            throw fail("缓存身份合同自检失败")
        }
        guard let resourceURL = Bundle.main.resourceURL else {
            throw fail("Click 资源目录不存在")
        }
        let unresolvedRoot = resourceURL
            .appendingPathComponent("ClickTTSRuntime", isDirectory: true)
            .standardizedFileURL
        let expectedUnresolvedRoot = resourceURL
            .standardizedFileURL
            .appendingPathComponent("ClickTTSRuntime", isDirectory: true)
            .standardizedFileURL
        guard unresolvedRoot.path == expectedUnresolvedRoot.path,
              let rootValues = try? unresolvedRoot.resourceValues(
                forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
              ),
              rootValues.isDirectory == true,
              rootValues.isSymbolicLink != true
        else {
            throw fail("Click 私有语音运行时不存在")
        }
        let root = unresolvedRoot
            .resolvingSymlinksInPath()
            .standardizedFileURL
        let expectedRoot = expectedUnresolvedRoot
            .resolvingSymlinksInPath()
            .standardizedFileURL
        guard root.path == expectedRoot.path else {
            throw fail("Click 私有语音运行时路径不一致")
        }
        let manifestURL = root.appendingPathComponent("runtime-manifest.json")
        let data = try Data(contentsOf: manifestURL)
        processCacheLock.lock()
        let cached = processVerification
        processCacheLock.unlock()
        if let cached {
            return try verifyCachedProcessRuntime(
                cached,
                root: root,
                manifestURL: manifestURL,
                manifestData: data,
                externalCheck: externalCheck,
                deadline: deadline
            )
        }
        guard let manifest = try JSONSerialization.jsonObject(with: data) as? [String: Any],
              (manifest["schema_version"] as? NSNumber)?.intValue == 1,
              manifest["runtime_id"] as? String == ClickTTSGate0Contract.expectedRuntimeID,
              let pythonInfo = manifest["python"] as? [String: Any],
              pythonInfo["version"] as? String == ClickTTSGate0Contract.expectedPythonVersion,
              pythonInfo["executable"] as? String == ClickTTSGate0Contract.pythonRelativePath,
              let provider = manifest["provider"] as? [String: Any],
              provider["name"] as? String == "edge-tts",
              provider["version"] as? String == ClickTTSGate0Contract.expectedEdgeTTSVersion,
              provider["helper"] as? String == ClickTTSGate0Contract.helperRelativePath,
              provider["ipc"] as? String == "jsonl-stdio",
              let target = manifest["target"] as? [String: Any],
              target["platform"] as? String == "macOS",
              target["architecture"] as? String == "arm64",
              let entries = manifest["files"] as? [[String: Any]],
              !entries.isEmpty
        else {
            throw fail("Click 私有语音运行时清单不匹配")
        }

        var declared = Set<String>()
        var fileStamps: [String: FileStamp] = [:]
        for entry in entries {
            try checkpoint(externalCheck, deadline: deadline)
            guard let relative = entry["path"] as? String,
                  !relative.isEmpty,
                  !relative.hasPrefix("/"),
                  !relative.split(separator: "/").contains(".."),
                  let expectedHash = entry["sha256"] as? String,
                  expectedHash.count == 64,
                  let expectedSize = (entry["size"] as? NSNumber)?.intValue,
                  let expectedMode = entry["mode"] as? String
            else {
                throw fail("运行时清单包含不安全路径")
            }
            let fileURL = root.appendingPathComponent(relative).standardizedFileURL
            let fileStamp = try stamp(fileURL, relativePath: relative)
            guard fileURL.path.hasPrefix(root.path + "/"),
                  fileStamp.size == expectedSize,
                  String(format: "%04o", fileStamp.mode) == expectedMode,
                  try ClickTTSGate0Contract.sha256File(
                    fileURL,
                    checkpoint: {
                        try checkpoint(externalCheck, deadline: deadline)
                    }
                  ) == expectedHash,
                  declared.insert(relative).inserted
            else {
                throw fail("运行时完整性校验失败：\(relative)")
            }
            fileStamps[relative] = fileStamp
        }

        guard let enumerator = FileManager.default.enumerator(
            at: root,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
            options: []
        ) else {
            throw fail("无法枚举语音运行时")
        }
        var actual = Set<String>()
        for case let url as URL in enumerator {
            try checkpoint(externalCheck, deadline: deadline)
            let values = try url.resourceValues(forKeys: [.isRegularFileKey, .isSymbolicLinkKey])
            if values.isSymbolicLink == true {
                throw fail("运行时包含符号链接：\(url.lastPathComponent)")
            }
            if values.isRegularFile == true {
                let canonicalURL = url
                    .resolvingSymlinksInPath()
                    .standardizedFileURL
                guard canonicalURL.path.hasPrefix(root.path + "/") else {
                    throw fail("运行时文件越出私有目录：\(url.lastPathComponent)")
                }
                let relative = String(canonicalURL.path.dropFirst(root.path.count + 1))
                if relative != "runtime-manifest.json" {
                    actual.insert(relative)
                }
            }
        }
        guard actual == declared else {
            throw fail("运行时文件树与签名清单不一致")
        }
        let verification = ProcessVerification(
            rootPath: root.path,
            manifestHash: ClickTTSGate0Contract.sha256(data),
            manifestStamp: try stamp(
                manifestURL,
                relativePath: "runtime-manifest.json"
            ),
            fileStamps: fileStamps,
            declared: declared
        )
        processCacheLock.lock()
        processVerification = verification
        processCacheLock.unlock()
        return try verifiedLocation(root: root)
    }
}

private struct ClickTTSGate0RequestContext {
    let fixtureID: String
    let chapterLocator: String
    let locatorRange: String

    static let custom = ClickTTSGate0RequestContext(
        fixtureID: ClickTTSGate0Contract.defaultFixtureID,
        chapterLocator: "probe-1",
        locatorRange: "0:0"
    )

    var cacheContext: [String: String] {
        ClickTTSGate0Contract.cacheContext(
            fixtureID: fixtureID,
            chapterLocator: chapterLocator,
            locatorRange: locatorRange
        )
    }
}

private struct ClickTTSGate0FixtureSegment {
    let fixtureID: String
    let title: String
    let text: String
    let chapterLocator: String
    let locatorRange: String

    var requestContext: ClickTTSGate0RequestContext {
        ClickTTSGate0RequestContext(
            fixtureID: fixtureID,
            chapterLocator: chapterLocator,
            locatorRange: locatorRange
        )
    }
}

