    case authorizationRequired
    case batchStarted
    case blockReady
    case playing
    case buffering
    case paused
    case sentenceBoundaryPaused
    case chapterBoundaryPaused
    case resumed
    case sentenceBoundary
    case horizonChanged
    case batchCompleted
    case bufferWarning
    case recoverableError
    case completed
    case stopped
}

struct ReadingTTSProductEvent {
