    private func speakChineseFallback(_ text: String) {
        let utterance = AVSpeechUtterance(string: text)
        utterance.voice = AVSpeechSynthesisVoice(language: "zh-CN")
        utterance.rate = 0.44
        speechSynthesizer.stopSpeaking(at: .immediate)
        speechSynthesizer.speak(utterance)
        statusLabel.stringValue = "正在朗读释义：\(text)"
    }

    private func updateVocabItemStatus(bookID: String, itemID: String, status: String, word: String) {
        DispatchQueue.global(qos: .utility).async { [readerAPI] in
            let ok = readerAPI.updateVocabItem(bookID: bookID, itemID: itemID, status: status)
            DispatchQueue.main.async {
                let title = Self.lookupStatusTitle(status)
                self.statusLabel.stringValue = ok ? "\(word) 已标记为\(title)" : "\(word) 状态更新失败"
            }
        }
    }

    private static func lookupLemma(from payload: [String: Any]?) -> String? {
        guard let item = payload?["item"] as? [String: Any] else {
            return nil
        }
        let lemma = lookupText(item["lemma"])
        return lemma.isEmpty ? nil : lemma
    }

    private static func firstLookupOccurrence(from payload: [String: Any]?) -> [String: Any]? {
        guard let occurrences = payload?["occurrences"] as? [[String: Any]] else {
            return nil
        }
        return occurrences.first
    }

    private static func lookupText(_ value: Any?) -> String {
        if let text = value as? String {
            return text
        }
        if let number = value as? NSNumber {
            return number.stringValue
        }
        if let bool = value as? Bool {
            return bool ? "true" : "false"
        }
        if let value {
            return "\(value)"
        }
        return ""
    }

    private static func lookupAlignmentTitle(_ status: String) -> String {
        switch status {
        case "confirmed_context_meaning":
            return "直译确认"
        case "paraphrased_context_meaning":
            return "上下文意译"
        case "context_sentence_available":
            return "有书内对应句"
        case "suspected_alignment_mismatch":
            return "疑似中英错配"
        case "needs_review":
            return "需要人工复核"
        case "missing_chinese_sentence":
            return "缺中文对应句"
        default:
            return status
        }
    }

    private static func lookupMeaningSourceTitle(_ source: String) -> String {
        switch source {
        case "lifestudy_domain_glossary": return "生命读经词库"
        case "book_glossary": return "本书术语表"
        case "user_glossary": return "用户修正"
        case "dictionary_fallback": return "本地词典"
        case "lifestudy_context": return "本书语境"
        default: return source
        }
    }

    private static func lookupPartOfSpeechTitle(primary: String, fallback: String) -> String {
        let raw = primary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? fallback : primary
        let key = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: ".", with: "")
            .replacingOccurrences(of: "_", with: " ")
            .lowercased()
        switch key {
        case "n", "noun", "名词":
            return "名词"
        case "v", "verb", "动词":
            return "动词"
        case "adj", "a", "adjective", "形容词":
            return "形容词"
        case "adv", "adverb", "副词":
            return "副词"
        case "proper noun", "proper_noun", "专有名词":
            return "专有名词"
        case "noun or verb", "noun_or_verb", "名词或动词":
            return "名词或动词"
        case "adjective or noun", "adjective_or_noun", "形容词或名词":
            return "形容词或名词"
        case "prep", "preposition", "介词":
            return "介词"
        case "conj", "conjunction", "连词":
            return "连词"
        case "pron", "pronoun", "代词":
            return "代词"
        case "num", "numeral", "number", "数词":
            return "数词"
        case "interj", "interjection", "感叹词":
            return "感叹词"
        case "article", "art", "冠词":
            return "冠词"
        default:
            return raw
        }
    }

    private static func lookupPartOfSpeechShortTitle(primary: String, fallback: String) -> String {
        let raw = primary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? fallback : primary
        let key = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: ".", with: "")
            .replacingOccurrences(of: "_", with: " ")
            .lowercased()
        switch key {
        case "n", "noun", "名词":
            return "n."
        case "v", "verb", "动词":
            return "v."
        case "adj", "a", "adjective", "形容词":
            return "adj."
        case "adv", "adverb", "副词":
            return "adv."
        case "proper noun", "proper_noun", "专有名词":
            return "prop. n."
        case "noun or verb", "noun_or_verb", "名词或动词":
            return "n./v."
        case "adjective or noun", "adjective_or_noun", "形容词或名词":
            return "adj./n."
        case "prep", "preposition", "介词":
            return "prep."
        case "conj", "conjunction", "连词":
            return "conj."
        case "pron", "pronoun", "代词":
            return "pron."
        case "num", "numeral", "number", "数词":
            return "num."
        case "interj", "interjection", "感叹词":
            return "interj."
        case "article", "art", "冠词":
            return "art."
        default:
            return raw
        }
    }

    private static func lookupStatusTitle(_ status: String) -> String {
        switch status {
        case "reviewing":
            return "复习"
        case "known":
            return "掌握"
        case "ignored":
            return "忽略"
        case "candidate":
            return "候选"
        case "saved":
            return "已保存"
        default:
            return status
        }
    }

    private func showNotePreview(sourceText: String, noteText: String, annotationID: String) {
        guard window.attachedSheet == nil else {
            return
        }

        let alert = NSAlert()
        alert.messageText = "注释"
        alert.informativeText = sourceText.isEmpty ? "当前句已有备注" : sourceText
        if annotationID.isEmpty {
            alert.addButton(withTitle: "关闭")
        } else {
            alert.addButton(withTitle: "编辑")
            alert.addButton(withTitle: "关闭")
        }

        let scroll = NSScrollView(frame: NSRect(x: 0, y: 0, width: 520, height: 150))
        let textView = NSTextView(frame: scroll.bounds)
        textView.font = NSFont(name: "Microsoft YaHei", size: 14) ?? NSFont.systemFont(ofSize: 14)
        textView.string = noteText.isEmpty ? "这条注释没有正文。" : noteText
        textView.isEditable = false
        textView.drawsBackground = false
        scroll.documentView = textView
        scroll.hasVerticalScroller = true
        alert.accessoryView = scroll

        alert.beginSheetModal(for: window) { response in
            guard !annotationID.isEmpty,
                  response == .alertFirstButtonReturn
            else {
                return
            }
            self.showExistingNoteEditor(annotationID: annotationID, sourceText: sourceText, noteText: noteText)
        }
    }

    private func showExistingNoteEditor(annotationID: String, sourceText: String, noteText: String) {
        let alert = NSAlert()
        alert.messageText = "编辑注释"
        alert.informativeText = sourceText
        alert.addButton(withTitle: "保存")
        alert.addButton(withTitle: "取消")

        let scroll = NSScrollView(frame: NSRect(x: 0, y: 0, width: 520, height: 150))
        let textView = NSTextView(frame: scroll.bounds)
        textView.font = NSFont(name: "Microsoft YaHei", size: 14) ?? NSFont.systemFont(ofSize: 14)
        textView.string = noteText
        scroll.documentView = textView
        scroll.hasVerticalScroller = true
        alert.accessoryView = scroll

        alert.beginSheetModal(for: window) { response in
            guard response == .alertFirstButtonReturn else {
                return
            }
            let updated = NoteTextNormalizer.normalized(textView.string)
            DispatchQueue.global(qos: .utility).async { [readerAPI = self.readerAPI] in
                let ok = readerAPI.updateAnnotation(annotationID: annotationID, noteText: updated, color: nil)
                DispatchQueue.main.async {
                    self.statusLabel.stringValue = ok ? "注释已更新" : "注释更新失败"
                    self.refreshNotes()
                    self.restoreAnnotationsForCurrentChapter()
                }
            }
        }
    }

    private func currentChapterLocator() -> String? {
        guard chapters.indices.contains(currentChapterIndex) else {
            return nil
        }
        return relativeChapterPath(for: chapters[currentChapterIndex])
    }

    private func annotationKey(chapterLocator: String, sentenceIndex: String) -> String {
        "\(chapterLocator)#\(sentenceIndex)"
    }

    private func sentenceIndexString(from rawIndex: Any?) -> String? {
        if let stringIndex = rawIndex as? String {
            let trimmed = stringIndex.trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? nil : trimmed
        }
        if let intIndex = rawIndex as? Int {
            return String(intIndex)
        }
        if let doubleIndex = rawIndex as? Double, doubleIndex.rounded() == doubleIndex {
            return String(Int(doubleIndex))
        }
        return nil
    }

    private func sentenceIndexList(from sentenceIndex: String) -> [String] {
        var seen = Set<String>()
        return sentenceIndex
            .split(separator: ",")
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .filter { index in
                if seen.contains(index) {
                    return false
                }
                seen.insert(index)
                return true
            }
    }

    private func sentenceIndexPayload(from payload: [String: Any]) -> String {
        if let indexes = payload["indexes"] as? [String], !indexes.isEmpty {
            return sentenceIndexList(from: indexes.joined(separator: ",")).joined(separator: ",")
        }
        if let indexes = payload["indexes"] as? [Any], !indexes.isEmpty {
            let joined = indexes.compactMap { sentenceIndexString(from: $0) }.joined(separator: ",")
            return sentenceIndexList(from: joined).joined(separator: ",")
        }
        return sentenceIndexString(from: payload["index"]) ?? ""
    }

    private func sentenceTargets(from payload: [String: Any]) -> [[String: Any]] {
        let rawTargets = payload["sentenceTargets"] as? [[String: Any]] ?? []
        let candidates: [[String: Any]]
        if rawTargets.isEmpty {
            let fallbackIndex = sentenceIndexPayload(from: payload)
            let fallbackLocator = (payload["locator"] as? String)?
                .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            let fallbackText = payload["text"] as? String ?? ""
            candidates = fallbackIndex.isEmpty ? [] : [[
                "sentenceIndex": fallbackIndex,
                "sentenceLocator": fallbackLocator,
                "sourceText": fallbackText,
            ]]
        } else {
            candidates = rawTargets
        }

        var seen = Set<String>()
        return candidates.compactMap { target in
            guard let sentenceIndex = sentenceIndexString(
                from: target["sentenceIndex"] ?? target["index"]
            ) else {
                return nil
            }
            let locator = (
                target["sentenceLocator"] as? String
                    ?? target["locator"] as? String
                    ?? ""
            ).trimmingCharacters(in: .whitespacesAndNewlines)
            let sourceText = target["sourceText"] as? String
                ?? target["text"] as? String
                ?? ""
            let key = "\(sentenceIndex)\u{1f}\(locator)\u{1f}\(sourceText)"
            guard seen.insert(key).inserted else {
                return nil
            }
            return [
                "sentenceIndex": sentenceIndex,
                "sentenceLocator": locator,
                "sourceText": sourceText,
            ]
        }
    }

    private func sentenceLocatorFields(
        targets: [[String: Any]]
    ) -> [String: Any] {
        var seen = Set<String>()
        let locators = targets.compactMap { target -> String? in
            let locator = (target["sentenceLocator"] as? String)?
                .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            guard !locator.isEmpty, seen.insert(locator).inserted else {
                return nil
            }
            return locator
        }
        var fields: [String: Any] = [
            "sentenceTargets": targets,
            "sentenceLocators": locators,
        ]
        if locators.count == 1 {
            fields["sentenceLocator"] = locators[0]
        }
        return fields
    }

    private func storedSentenceLocatorFields(
        range: [String: Any],
        metadata: [String: Any]
    ) -> [String: Any] {
        var fields: [String: Any] = [:]
        for key in [
            "sentenceLocator",
            "sentenceLocators",
            "sentenceTargets",
        ] {
            if let value = range[key] ?? metadata[key] {
                fields[key] = value
            }
        }
        return fields
    }

    private func storedSentenceTargets(
        range: [String: Any],
        metadata: [String: Any]
    ) -> [[String: Any]] {
        for rawValue in [
            range["sentenceTargets"],
            metadata["sentenceTargets"],
        ] {
            guard let targets = rawValue as? [[String: Any]] else {
                continue
            }
            let normalized = sentenceTargets(from: [
                "sentenceTargets": targets,
            ])
            if !normalized.isEmpty {
                return normalized
            }
        }
        return []
    }

    private func sentenceTargets(
        fromSelectionFragments fragments: [[String: Any]]
    ) -> [[String: Any]] {
        let rawTargets = fragments.compactMap { fragment -> [String: Any]? in
            guard let sentenceIndex = sentenceIndexString(
                from: fragment["sentenceIndex"]
            ) else {
                return nil
            }
            return [
                "sentenceIndex": sentenceIndex,
                "sentenceLocator": fragment["sentenceLocator"] as? String ?? "",
                "sourceText": fragment["sentenceSourceText"] as? String ?? "",
            ]
        }
        return sentenceTargets(from: [
            "sentenceTargets": rawTargets,
        ])
    }

    private func firstStoredSentenceLocator(
        range: [String: Any],
        metadata: [String: Any]
    ) -> String {
        for rawValue in [
            range["sentenceLocator"],
            metadata["sentenceLocator"],
        ] {
            let locator = (rawValue as? String)?
                .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            if !locator.isEmpty {
                return locator
            }
        }
        for rawValue in [
            range["sentenceLocators"],
            metadata["sentenceLocators"],
        ] {
            let locator = (rawValue as? [Any])?
                .compactMap { ($0 as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) }
                .first { !$0.isEmpty } ?? ""
            if !locator.isEmpty {
                return locator
            }
        }
        for rawValue in [
            range["sentenceTargets"],
            metadata["sentenceTargets"],
        ] {
            let locator = (rawValue as? [[String: Any]])?
                .compactMap {
                    ($0["sentenceLocator"] as? String)?
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                }
                .first { !$0.isEmpty } ?? ""
            if !locator.isEmpty {
                return locator
            }
        }
        return ""
    }

    private func annotationIDsPayload(from payload: [String: Any]) -> [String] {
        let rawIDs = payload["annotationIDs"] as? [Any] ?? []
        var seen = Set<String>()
        return rawIDs.compactMap { rawID in
            guard let rawID = rawID as? String else {
                return nil
            }
            let annotationID = rawID.trimmingCharacters(
                in: .whitespacesAndNewlines
            )
            guard !annotationID.isEmpty,
                  seen.insert(annotationID).inserted
            else {
                return nil
            }
            return annotationID
        }
    }

    private func integerValue(from rawValue: Any?) -> Int? {
        if let intValue = rawValue as? Int {
            return intValue
        }
        if let doubleValue = rawValue as? Double, doubleValue.rounded() == doubleValue {
            return Int(doubleValue)
        }
        if let numberValue = rawValue as? NSNumber {
            return numberValue.intValue
        }
        if let stringValue = rawValue as? String {
            return Int(stringValue.trimmingCharacters(in: .whitespacesAndNewlines))
        }
        return nil
    }

    private func selectionFragments(from payload: [String: Any]) -> [[String: Any]] {
        guard let rawFragments = payload["fragments"] as? [[String: Any]] else {
            return []
        }
        return rawFragments.compactMap { fragment in
            guard let sentenceIndex = sentenceIndexString(from: fragment["sentenceIndex"]),
                  let startOffset = integerValue(from: fragment["startOffset"]),
                  let endOffset = integerValue(from: fragment["endOffset"]),
                  endOffset > startOffset
            else {
                return nil
            }
            var normalized: [String: Any] = [
                "sentenceIndex": sentenceIndex,
                "startOffset": startOffset,
                "endOffset": endOffset,
                "text": fragment["text"] as? String ?? "",
            ]
            let locator = (fragment["sentenceLocator"] as? String)?
                .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            if !locator.isEmpty {
                normalized["sentenceLocator"] = locator
            }
            if let sourceText = fragment["sentenceSourceText"] as? String,
               !sourceText.isEmpty {
                normalized["sentenceSourceText"] = sourceText
            }
            return normalized
        }
    }

    private func selectionFragmentKey(_ fragment: [String: Any]) -> String? {
        guard let sentenceIndex = sentenceIndexString(from: fragment["sentenceIndex"]),
              let startOffset = integerValue(from: fragment["startOffset"]),
              let endOffset = integerValue(from: fragment["endOffset"]),
              endOffset > startOffset
        else {
            return nil
        }
        let locator = (fragment["sentenceLocator"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let sourceText = (fragment["sentenceSourceText"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let identity = locator.isEmpty || sourceText.isEmpty
            ? "index:\(sentenceIndex)"
            : "locator:\(locator):\(sourceText)"
        return "\(identity):\(startOffset):\(endOffset)"
    }

    private func selectionFragmentKeys(from fragments: [[String: Any]]) -> Set<String> {
        Set(fragments.compactMap { selectionFragmentKey($0) })
    }

    private func selectionFragments(fromRawFragments rawFragments: Any?) -> [[String: Any]] {
        guard let rawFragments = rawFragments as? [[String: Any]] else {
            return []
        }
        return selectionFragments(from: ["fragments": rawFragments])
    }

    private func persistNote(
        sentence: String,
        sentenceIndex: String,
        noteText: String,
        audioNoteID: String? = nil,
        selectionFragments: [[String: Any]] = [],
        selectionMode: String? = nil,
        sentenceTargets: [[String: Any]] = []
    ) {
        guard let bookID = readerBookID,
              let chapterLocator = currentChapterLocator(),
              !noteText.isEmpty
        else {
            statusLabel.stringValue = noteText.isEmpty ? "备注为空，未保存" : "Reader API 未连接，备注未写入数据库"
            return
        }
        let chapterTitle = chapterTitles.indices.contains(currentChapterIndex) ? chapterTitles[currentChapterIndex] : nil
        var rangeLocator: [String: Any] = [
            "chapterLocator": chapterLocator,
            "sentenceIndex": sentenceIndex,
        ]
        var metadata: [String: Any] = [
            "source": "SentenceReaderNative",
            "sentenceIndex": sentenceIndex,
        ]
        for (key, value) in sentenceLocatorFields(targets: sentenceTargets) {
            rangeLocator[key] = value
            metadata[key] = value
        }
        if let selectionMode, !selectionFragments.isEmpty {
            rangeLocator["mode"] = selectionMode
            rangeLocator["fragments"] = selectionFragments
            metadata["mode"] = selectionMode
            metadata["fragments"] = selectionFragments
        }
        statusLabel.stringValue = "正在保存备注到 Reader API..."
        DispatchQueue.global(qos: .utility).async { [readerAPI] in
            let annotationID = readerAPI.createAnnotation(
                bookID: bookID,
                kind: "note",
                sourceText: sentence,
                noteText: noteText,
                color: nil,
                chapterTitle: chapterTitle,
                chapterLocator: chapterLocator,
                sentenceIndex: sentenceIndex,
                rangeLocator: rangeLocator,
                metadata: metadata
            )
            DispatchQueue.main.async {
                self.statusLabel.stringValue = annotationID == nil ? "备注保存失败：Reader API 未写入" : "已保存备注到 Reader API"
                if let annotationID,
                   let audioNoteID {
                    DispatchQueue.global(qos: .utility).async { [readerAPI = self.readerAPI] in
                        _ = readerAPI.updateAudioNote(
                            audioNoteID: audioNoteID,
                            annotationID: annotationID,
                            provider: nil,
                            transcript: nil,
                            status: nil,
                            errorMessage: nil
                        )
                    }
                }
                self.refreshNotes()
                self.restoreAnnotationsForCurrentChapter()
            }
        }
    }

    private func persistSelectionRed(
        sentence: String,
        sentenceIndex: String,
        fragments: [[String: Any]],
        sentenceTargets: [[String: Any]]
    ) {
        guard let bookID = readerBookID,
              let chapterLocator = currentChapterLocator(),
              !sentenceIndex.isEmpty,
              !fragments.isEmpty
        else {
            statusLabel.stringValue = "选中文字红标未保存：Reader API 未连接或选区为空"
            return
        }
        let chapterTitle = chapterTitles.indices.contains(currentChapterIndex) ? chapterTitles[currentChapterIndex] : nil
        var rangeLocator: [String: Any] = [
            "chapterLocator": chapterLocator,
            "sentenceIndex": sentenceIndex,
            "mode": "text_selection",
            "fragments": fragments,
        ]
        var metadata: [String: Any] = [
            "source": "SentenceReaderNative",
            "sentenceIndex": sentenceIndex,
            "mode": "text_selection",
            "fragments": fragments,
        ]
        for (key, value) in sentenceLocatorFields(targets: sentenceTargets) {
            rangeLocator[key] = value
            metadata[key] = value
        }
        DispatchQueue.global(qos: .utility).async { [readerAPI] in
            let annotationID = readerAPI.createAnnotation(
                bookID: bookID,
                kind: "red_highlight",
                sourceText: sentence,
                noteText: nil,
                color: "red",
                chapterTitle: chapterTitle,
                chapterLocator: chapterLocator,
                sentenceIndex: sentenceIndex,
                rangeLocator: rangeLocator,
                metadata: metadata
            )
            DispatchQueue.main.async {
                self.statusLabel.stringValue = annotationID == nil ? "选中文字红标保存失败" : "选中文字红标已保存到 Reader API"
                self.refreshNotes()
                self.restoreAnnotationsForCurrentChapter()
            }
        }
    }

    private func deleteSelectionRed(
        sentenceIndex: String,
        fragments: [[String: Any]],
        requestedAnnotationIDs: [String]
    ) {
        guard let bookID = readerBookID,
              let chapterLocator = currentChapterLocator(),
              !sentenceIndex.isEmpty,
              !fragments.isEmpty
        else {
            statusLabel.stringValue = "选中文字红标未撤回：Reader API 未连接或选区为空"
            return
        }

        let targetKeys = selectionFragmentKeys(from: fragments)
        guard !targetKeys.isEmpty else {
            statusLabel.stringValue = "选中文字红标未撤回：选区范围为空"
            return
        }

        DispatchQueue.global(qos: .utility).async { [readerAPI] in
            let annotations = readerAPI.listAnnotations(bookID: bookID)
            var exactIDs: [String] = []
            var overlappingIDs: [String] = []
            var validatedRequestedIDs: [String] = []
            let requestedIDSet = Set(requestedAnnotationIDs)

            for annotation in annotations {
                guard let annotationID = annotation["id"] as? String,
                      annotation["kind"] as? String == "red_highlight",
                      annotation["chapter_locator"] as? String == chapterLocator
                else {
                    continue
                }
                let range = annotation["range_locator"] as? [String: Any] ?? [:]
                let metadata = annotation["metadata"] as? [String: Any] ?? [:]
                let mode = range["mode"] as? String ?? metadata["mode"] as? String ?? ""
                guard mode == "text_selection" else {
                    continue
                }
                if requestedIDSet.contains(annotationID) {
                    validatedRequestedIDs.append(annotationID)
                }

                let rangeFragments = self.selectionFragments(fromRawFragments: range["fragments"])
                let annotationFragments = rangeFragments.isEmpty
                    ? self.selectionFragments(fromRawFragments: metadata["fragments"])
                    : rangeFragments
                let annotationKeys = self.selectionFragmentKeys(from: annotationFragments)
                guard !annotationKeys.isEmpty else {
                    continue
                }
                if annotationKeys == targetKeys {
                    exactIDs.append(annotationID)
                } else if !annotationKeys.isDisjoint(with: targetKeys) {
                    overlappingIDs.append(annotationID)
                }
            }

            let matchedIDs = Set(exactIDs.isEmpty ? overlappingIDs : exactIDs)
            let idsToDelete = requestedIDSet.isEmpty
                ? matchedIDs
                : Set(validatedRequestedIDs)
            var allDeleted = true
            for annotationID in idsToDelete {
                allDeleted = readerAPI.deleteAnnotation(annotationID: annotationID) && allDeleted
            }

            DispatchQueue.main.async {
                if idsToDelete.isEmpty {
                    self.statusLabel.stringValue = "没有找到可撤回的选中文字红标"
                } else {
                    self.statusLabel.stringValue = allDeleted ? "选中文字红标已撤回" : "选中文字红标撤回失败，已恢复数据库状态"
                }
                self.refreshNotes()
                self.restoreAnnotationsForCurrentChapter()
            }
        }
    }

    private func persistRed(
        sentence: String,
        sentenceIndex: String,
        isRed: Bool,
        sentenceTargets: [[String: Any]],
        requestedAnnotationIDs: [String]
    ) {
        guard let bookID = readerBookID,
              let chapterLocator = currentChapterLocator(),
              !sentenceIndex.isEmpty
        else {
            return
        }
        let indexList = sentenceIndexList(from: sentenceIndex)
        guard !indexList.isEmpty else {
            return
        }
        let keys = indexList.map { annotationKey(chapterLocator: chapterLocator, sentenceIndex: $0) }
        let chapterTitle = chapterTitles.indices.contains(currentChapterIndex) ? chapterTitles[currentChapterIndex] : nil
        if isRed {
            let missingPairs = zip(indexList, keys).filter { _, key in redAnnotationIDs[key] == nil }
            if missingPairs.isEmpty {
                return
            }
            let missingIndexes = missingPairs.map { index, _ in index }
            let missingKeys = missingPairs.map { _, key in key }
            let missingSentenceIndex = missingIndexes.joined(separator: ",")
            let missingIndexSet = Set(missingIndexes)
            let missingTargets = sentenceTargets.filter { target in
                guard let index = self.sentenceIndexString(
                    from: target["sentenceIndex"]
                ) else {
                    return false
                }
                return missingIndexSet.contains(index)
            }
            var rangeLocator: [String: Any] = [
                "chapterLocator": chapterLocator,
                "sentenceIndex": missingSentenceIndex,
            ]
            var metadata: [String: Any] = [
                "source": "SentenceReaderNative",
                "sentenceIndex": missingSentenceIndex,
            ]
            for (key, value) in sentenceLocatorFields(
                targets: missingTargets
            ) {
                rangeLocator[key] = value
                metadata[key] = value
            }
            DispatchQueue.global(qos: .utility).async { [readerAPI] in
                let annotationID = readerAPI.createAnnotation(
                    bookID: bookID,
                    kind: "red_highlight",
                    sourceText: sentence,
                    noteText: nil,
                    color: "red",
                    chapterTitle: chapterTitle,
                    chapterLocator: chapterLocator,
                    sentenceIndex: missingSentenceIndex,
                    rangeLocator: rangeLocator,
                    metadata: metadata
                )
                DispatchQueue.main.async {
                    if let annotationID {
                        for key in missingKeys {
                            self.redAnnotationIDs[key] = annotationID
                        }
                        self.statusLabel.stringValue = "红标已保存到 Reader API"
                    } else {
                        self.statusLabel.stringValue = "红标保存失败，已恢复数据库状态"
                        self.restoreAnnotationsForCurrentChapter()
                    }
                    self.refreshNotes()
                }
            }
            return
        }

        let annotationIDs = Set(keys.compactMap { redAnnotationIDs[$0] })
            .union(requestedAnnotationIDs)
        for key in keys {
            redAnnotationIDs[key] = nil
        }
        guard !annotationIDs.isEmpty else {
            refreshNotes()
            return
        }
        DispatchQueue.global(qos: .utility).async { [readerAPI] in
            let allowedIDs = Set(
                readerAPI.listAnnotations(bookID: bookID).compactMap {
                    annotation -> String? in
                    guard annotation["kind"] as? String == "red_highlight",
                          annotation["chapter_locator"] as? String
                            == chapterLocator,
                          let annotationID = annotation["id"] as? String,
                          annotationIDs.contains(annotationID)
                    else {
                        return nil
                    }
                    return annotationID
                }
            )
            var allDeleted = true
            for annotationID in allowedIDs {
                allDeleted = readerAPI.deleteAnnotation(annotationID: annotationID) && allDeleted
            }
            DispatchQueue.main.async {
                if allowedIDs.isEmpty {
                    self.statusLabel.stringValue = "没有找到可取消的红标"
                } else {
                    self.statusLabel.stringValue = allDeleted ? "红标取消已保存到 Reader API" : "红标取消保存失败，已恢复数据库状态"
                }
                self.refreshNotes()
                self.restoreAnnotationsForCurrentChapter()
            }
        }
    }

    private func restoreAnnotationsForCurrentChapter() {
        if isPDFReadingMode {
            restorePDFAnnotations()
            return
        }
        guard let bookID = readerBookID,
              let chapterLocator = currentChapterLocator()
        else {
            return
        }

        DispatchQueue.global(qos: .utility).async { [readerAPI] in
            let annotations = readerAPI.listAnnotations(bookID: bookID)
            var redItems: [[String: Any]] = []
            var selectionRedFragments: [[String: Any]] = []
            var noteItems: [[String: Any]] = []
            for annotation in annotations {
                guard let kind = annotation["kind"] as? String,
                      annotation["chapter_locator"] as? String == chapterLocator,
                      let id = annotation["id"] as? String
                else {
                    continue
                }
                let range = annotation["range_locator"] as? [String: Any] ?? [:]
                let metadata = annotation["metadata"] as? [String: Any] ?? [:]
                guard let rawIndex = self.sentenceIndexString(from: range["sentenceIndex"] ?? metadata["sentenceIndex"]) else {
                    continue
                }
                let indexes = self.sentenceIndexList(from: rawIndex)
                guard !indexes.isEmpty else {
                    continue
                }

                if kind == "red_highlight" {
                    let mode = range["mode"] as? String ?? metadata["mode"] as? String ?? ""
                    if mode == "text_selection" {
                        let fragments = range["fragments"] as? [[String: Any]]
                            ?? metadata["fragments"] as? [[String: Any]]
                            ?? []
                        for var fragment in fragments {
                            fragment["annotationID"] = id
                            fragment["annotationSourceText"] =
                                annotation["source_text"] as? String ?? ""
                            selectionRedFragments.append(fragment)
                        }
                        continue
                    }
                    var item: [String: Any] = [
                        "id": id,
                        "index": indexes.joined(separator: ","),
                        "indexes": indexes,
                        "sourceText": annotation["source_text"] as? String ?? "",
                    ]
                    for (key, value) in self.storedSentenceLocatorFields(
                        range: range,
                        metadata: metadata
                    ) {
                        item[key] = value
                    }
                    redItems.append(item)
                    continue
                }

                if kind == "note" {
                    var item: [String: Any] = [
                        "id": id,
                        "index": indexes.joined(separator: ","),
                        "indexes": indexes,
                        "sourceText": annotation["source_text"] as? String ?? "",
                        "noteText": annotation["note_text"] as? String ?? "",
                    ]
                    for (key, value) in self.storedSentenceLocatorFields(
                        range: range,
                        metadata: metadata
                    ) {
                        item[key] = value
                    }
                    noteItems.append(item)
                }
            }

            DispatchQueue.main.async {
                let prefix = "\(chapterLocator)#"
                self.redAnnotationIDs = self.redAnnotationIDs.filter { !$0.key.hasPrefix(prefix) }
                let payload: [String: Any] = [
                    "redItems": redItems,
                    "selectionRedFragments": selectionRedFragments,
                    "notes": noteItems,
                ]
                if let data = try? JSONSerialization.data(withJSONObject: payload),
                   let json = String(data: data, encoding: .utf8) {
                    self.webView.evaluateJavaScript("window.__sentenceReaderApplyAnnotations && window.__sentenceReaderApplyAnnotations(\(json));")
                }
            }
        }
    }

